def _opt() -> Any:
    return optional_module("fi.opt", _OPTIMIZE_EXTRA)


def _manifest() -> Any:
    return optional_module("fi.simulate.manifest", "simulate")


def _suite() -> Any:
    return optional_module("fi.simulate.suite", "simulate")


def _agent_learning_suite() -> Any:
    return optional_module("fi.alk.suite", "trinity")


def diagnose_text(*args: Any, **kwargs: Any) -> Any:
    return _opt().diagnose_text(*args, **kwargs)


def diagnose_report(*args: Any, **kwargs: Any) -> Any:
    return _opt().diagnose_report(*args, **kwargs)


def relevant_search_paths(*args: Any, **kwargs: Any) -> Any:
    return _opt().relevant_search_paths(*args, **kwargs)


def optimize_manifest_file(
    path: str | Path,
    *,
    options: Optional[Any] = None,
    name: Optional[str] = None,
    threshold: Optional[float] = None,
    max_candidates: Optional[int] = None,
    dry_run: Optional[bool] = None,
) -> dict[str, Any]:
    payload = _manifest().optimize_manifest_file(
        path,
        options=options,
        name=name,
        threshold=threshold,
        max_candidates=max_candidates,
        dry_run=dry_run,
    )
    payload = with_optimization_candidate_lineage(payload)
    payload = with_optimization_governance(payload)
    payload = with_redteam_campaign_proof(payload)
    payload = with_redteam_attack_evolution_proof(payload)
    payload = with_framework_runtime_proof(payload)
    payload = with_world_hook_proof(payload)
    payload = with_workflow_hook_proof(payload)
    payload = with_retrieval_hook_proof(payload)
    payload = with_evaluation_hook_proof(payload)
    payload = with_framework_certification_proof(payload)
    payload = with_framework_adapter_matrix_proof(payload)
    payload = with_workspace_import_certification_proof(payload)
    payload = with_retrospective_harness_proof(payload)
    payload = with_optimizer_portfolio_proof(payload)
    payload = with_memory_lineage_proof(payload)
    payload = with_multi_agent_coordination_proof(payload)
    payload = with_orchestration_stack_proof(payload)
    payload = with_optimizer_trajectory_profile(payload)
    payload = with_whole_agent_apply_plan(payload)
    return public_payload(payload, kind=AGENT_LEARNING_OPTIMIZATION_KIND)


def optimize_manifest(
    manifest: Mapping[str, Any],
    *,
    manifest_path: str | Path = ".",
    options: Optional[Any] = None,
    name: Optional[str] = None,
    threshold: Optional[float] = None,
    max_candidates: Optional[int] = None,
    dry_run: Optional[bool] = None,
) -> dict[str, Any]:
    payload = _manifest().optimize_manifest(
        manifest,
        manifest_path=manifest_path,
        options=options,
        name=name,
        threshold=threshold,
        max_candidates=max_candidates,
        dry_run=dry_run,
    )
    payload = with_optimization_candidate_lineage(payload)
    payload = with_optimization_governance(payload)
    payload = with_redteam_campaign_proof(payload)
    payload = with_redteam_attack_evolution_proof(payload)
    payload = with_framework_runtime_proof(payload)
    payload = with_world_hook_proof(payload)
    payload = with_workflow_hook_proof(payload)
    payload = with_retrieval_hook_proof(payload)
    payload = with_evaluation_hook_proof(payload)
    payload = with_framework_certification_proof(payload)
    payload = with_framework_adapter_matrix_proof(payload)
    payload = with_workspace_import_certification_proof(payload)
    payload = with_retrospective_harness_proof(payload)
    payload = with_optimizer_portfolio_proof(payload)
    payload = with_memory_lineage_proof(payload)
    payload = with_multi_agent_coordination_proof(payload)
    payload = with_orchestration_stack_proof(payload)
    payload = with_optimizer_trajectory_profile(payload)
    payload = with_whole_agent_apply_plan(payload)
    return public_payload(payload, kind=AGENT_LEARNING_OPTIMIZATION_KIND)


def with_world_hook_proof(payload: Mapping[str, Any]) -> dict[str, Any]:
    """Attach a native proof contract for world-model/world-hook optimizations."""

    result = copy.deepcopy(dict(payload))
    optimization = _plain_mapping(result.get("optimization"))
    source_manifest = _plain_mapping(optimization.get("source_manifest"))
    source_metadata = _plain_mapping(source_manifest.get("metadata"))
    source_optimization = _plain_mapping(source_manifest.get("optimization"))
    target = _plain_mapping(_plain_mapping(source_optimization.get("target")))
    metadata = {
        **source_metadata,
        **_plain_mapping(target.get("metadata")),
    }
    task_kind = _scope_key(metadata.get("task_kind"))
    if task_kind not in {"world_model", "world_hooks"}:
        return result

    proof = _world_hook_proof(result, optimization, target_metadata=metadata)
    result["world_hook_proof"] = proof
    optimization["world_hook_proof"] = copy.deepcopy(proof)
    result["optimization"] = optimization

    summary = _plain_mapping(result.get("summary"))
    summary["world_hook_proof_status"] = proof["status"]
    summary["world_hook_proof_passed"] = proof["passed"]
    summary["world_hook_proof_assurance_level"] = proof["assurance_level"]
    summary["world_hook_proof_check_count"] = proof["check_count"]
    summary["world_hook_proof_failed_check_count"] = len(proof["failed_check_ids"])
    summary["world_hook_proof_warning_check_count"] = len(
        proof["warning_check_ids"]
    )
    result["summary"] = summary
    return result


