def optimize_framework_adapter_probe(
    *,
    name: str,
    framework: str,
    adapter_candidates: Optional[Sequence[Mapping[str, Any]]] = None,
    agent: Any = None,
    agent_factory: Optional[Callable[[], Any]] = None,
    cases: Sequence[Mapping[str, Any]] = (),
    target: str | None = None,
    target_base_dir: str | Path = ".",
    target_factory: Optional[bool] = None,
    method_candidates: Optional[Sequence[str | None]] = None,
    input_mode_candidates: Optional[Sequence[str]] = None,
    threshold: float = 0.9,
    trace_runtime: bool = True,
    allow_external_target: bool = False,
    metadata: Optional[Mapping[str, Any]] = None,
    discovery_max_candidates: Optional[int] = 8,
    max_candidates: Optional[int] = None,
    include_seed: bool = True,
) -> dict[str, Any]:
    """Optimize framework adapter method/input candidates with local probes.

    This is the direct SDK path before a user has a full simulation manifest:
    pass a local framework object or factory, optional candidate adapter specs,
    and probe cases. When ``adapter_candidates`` is omitted, the helper first
    runs local framework adapter discovery and then probes the discovered
    candidates. If no live object is supplied, a local ``target`` string such
    as ``"path/to/app.py:Agent"`` or ``"package.module:factory"`` is resolved
    before probing. It returns a normal ``agent-learning.optimization.v1``
    artifact with candidate lineage, optimizer governance, discovery evidence,
    and a probe-specific proof.
    """

    if not name:
        raise ValueError("name is required")
    if not framework:
        raise ValueError("framework is required")
    agent, agent_factory, _ = _resolve_framework_probe_agent(
        agent=agent,
        agent_factory=agent_factory,
        target=target,
        target_base_dir=target_base_dir,
        target_factory=target_factory,
    )
    if agent is None and agent_factory is None:
        raise ValueError("agent, agent_factory, or a local target is required")
    discovery_result: dict[str, Any] | None = None
    candidate_source = "explicit"
    if adapter_candidates:
        active_adapter_candidates = [
            copy.deepcopy(dict(candidate)) for candidate in adapter_candidates
        ]
    else:
        discovery_result = _discover_framework_probe_candidates(
            framework=framework,
            agent=agent,
            agent_factory=agent_factory,
            target=target,
            method_candidates=method_candidates,
            input_mode_candidates=input_mode_candidates,
            trace_runtime=trace_runtime,
            allow_external_target=allow_external_target,
            metadata=metadata,
            max_candidates=discovery_max_candidates,
        )
        active_adapter_candidates = [
            copy.deepcopy(dict(candidate))
            for candidate in _plain_list(discovery_result.get("adapter_candidates"))
            if isinstance(candidate, Mapping)
        ]
        candidate_source = "discovery"
    if not active_adapter_candidates:
        raise ValueError("adapter_candidates must contain at least one candidate")

    candidate_configs = [
        _framework_probe_candidate_config(
            candidate,
            target=target,
            trace_runtime=trace_runtime,
            allow_external_target=allow_external_target,
        )
        for candidate in active_adapter_candidates
    ]
    first_config = candidate_configs[0]
    opt = _opt()
    optimizer_module = optional_module("fi.opt.optimizers", _OPTIMIZE_EXTRA)
    optimization_target = opt.OptimizationTarget(
        name=name,
        layers=["framework", "integration", "harness", "evaluator"],
        base_config={
            "framework": framework,
            "target": target,
            "adapter": copy.deepcopy(first_config),
        },
        search_space={"adapter": copy.deepcopy(candidate_configs)},
        metadata={
            "source": "fi.alk.optimize.optimize_framework_adapter_probe",
            "task_kind": "framework_adapter_probe",
            "framework": framework,
            "adapter_candidate_source": candidate_source,
            "framework_adapter_discovery_used": discovery_result is not None,
            "framework_adapter_discovery_summary": copy.deepcopy(
                _plain_mapping(discovery_result.get("summary"))
                if discovery_result is not None
                else {}
            ),
            **copy.deepcopy(dict(metadata or {})),
        },
    )

    def evaluate_candidate(candidate: Any) -> Any:
        adapter = _plain_mapping(_plain_mapping(candidate.config).get("adapter"))
        probe_result = _run_framework_probe_candidate(
            framework=framework,
            agent=agent_factory() if agent_factory is not None else agent,
            adapter=adapter,
            cases=cases,
            target=target,
            metadata=metadata,
            default_trace_runtime=trace_runtime,
            default_allow_external_target=allow_external_target,
        )
        scoring = score_framework_adapter_probe_result(
            probe_result,
            require_tool_evidence=_probe_requires_tool_evidence(adapter, cases),
        )
        return opt.CandidateEvaluation(
            candidate=candidate,
            score=float(scoring["score"]),
            reason=str(scoring["reason"]),
            report=copy.deepcopy(probe_result),
            metadata={
                "candidate_patch": copy.deepcopy(candidate.patch),
                "patch": copy.deepcopy(candidate.patch),
                "search_paths": list(candidate.metadata.get("search_paths", [])),
                "metrics": copy.deepcopy(scoring["metrics"]),
                "findings": copy.deepcopy(probe_result.get("findings", [])),
                "report_summary": copy.deepcopy(probe_result.get("summary", {})),
                "evaluation_score": float(scoring["score"]),
                "evaluation_passed": bool(scoring["passed"]),
            },
        )

    optimizer = optimizer_module.AgentOptimizer(
        target=optimization_target,
        evaluate_candidate=evaluate_candidate,
        max_candidates=max_candidates,
        include_seed=include_seed,
        auto_diagnose=False,
    )
    optimization_result = optimizer.optimize()
    payload = _framework_probe_optimization_payload(
        name=name,
        framework=framework,
        target=target,
        threshold=threshold,
        optimization_result=optimization_result,
        metadata=metadata,
        discovery_result=discovery_result,
        candidate_source=candidate_source,
    )
    payload = with_optimization_candidate_lineage(payload)
    payload = with_optimization_governance(payload)
    payload = _with_framework_adapter_probe_proof(payload)
    return public_payload(payload, kind=AGENT_LEARNING_OPTIMIZATION_KIND)


def build_framework_run_manifest_from_local_adapter(
    *,
    name: str,
    framework: str,
    target: str,
    adapter_candidates: Optional[Sequence[Mapping[str, Any]]] = None,
    agent: Any = None,
    agent_factory: Optional[Callable[[], Any]] = None,
    cases: Sequence[Mapping[str, Any]] = (),
    target_base_dir: str | Path = ".",
    target_factory: Optional[bool] = None,
    method_candidates: Optional[Sequence[str | None]] = None,
    input_mode_candidates: Optional[Sequence[str]] = None,
    required_env: Sequence[str] = (),
    scenario: Optional[Mapping[str, Any]] = None,
    framework_trace: Optional[Mapping[str, Any]] = None,
    evaluation_config: Optional[Mapping[str, Any]] = None,
    auto_evaluation_config: bool = True,
    threshold: float = 0.9,
    trace_runtime: bool = True,
    allow_external_target: bool = False,
    metadata: Optional[Mapping[str, Any]] = None,
    discovery_max_candidates: Optional[int] = 8,
    max_candidates: Optional[int] = None,
    include_seed: bool = True,
    factory: Optional[bool] = None,
    min_turns: int = 1,
    max_turns: int = 1,
) -> dict[str, Any]:
    """Optimize a local framework adapter and return a promoted run manifest.

    ``agent`` or ``agent_factory`` may be supplied directly. When they are
    omitted, the helper resolves the local ``target`` string and probes that
    callable before writing the promoted manifest.
    """

    if not name:
        raise ValueError("name is required")
    if not target:
        raise ValueError("target is required")

    agent, agent_factory, inferred_target_factory = _resolve_framework_probe_agent(
        agent=agent,
        agent_factory=agent_factory,
        target=target,
        target_base_dir=target_base_dir,
        target_factory=target_factory,
    )
    selected_factory = (
        factory
        if factory is not None
        else inferred_target_factory
    )
    optimization_result = optimize_framework_adapter_probe(
        name=f"{name}-adapter-probe",
        framework=framework,
        target=target,
        target_base_dir=target_base_dir,
        target_factory=target_factory,
        adapter_candidates=adapter_candidates,
        agent=agent,
        agent_factory=agent_factory,
        cases=cases,
        method_candidates=method_candidates,
        input_mode_candidates=input_mode_candidates,
        threshold=threshold,
        trace_runtime=trace_runtime,
        allow_external_target=allow_external_target,
        metadata=metadata,
        discovery_max_candidates=discovery_max_candidates,
        max_candidates=max_candidates,
        include_seed=include_seed,
    )
    return build_framework_run_manifest_from_probe_optimization(
        optimization_result,
        name=name,
        target=target,
        required_env=required_env,
        scenario=scenario,
        framework_trace=framework_trace,
        evaluation_config=evaluation_config,
        auto_evaluation_config=auto_evaluation_config,
        threshold=threshold,
        metadata={
            "source": "fi.alk.optimize.build_framework_run_manifest_from_local_adapter",
            **copy.deepcopy(dict(metadata or {})),
        },
        factory=selected_factory,
        min_turns=min_turns,
        max_turns=max_turns,
    )


async def run_framework_adapter_from_local_adapter(
    *,
    name: str,
    framework: str,
    target: str,
    adapter_candidates: Optional[Sequence[Mapping[str, Any]]] = None,
    agent: Any = None,
    agent_factory: Optional[Callable[[], Any]] = None,
    cases: Sequence[Mapping[str, Any]] = (),
    target_base_dir: str | Path = ".",
    target_factory: Optional[bool] = None,
    method_candidates: Optional[Sequence[str | None]] = None,
    input_mode_candidates: Optional[Sequence[str]] = None,
    required_env: Sequence[str] = (),
    scenario: Optional[Mapping[str, Any]] = None,
    framework_trace: Optional[Mapping[str, Any]] = None,
    evaluation_config: Optional[Mapping[str, Any]] = None,
    auto_evaluation_config: bool = True,
    threshold: float = 0.9,
    trace_runtime: bool = True,
    allow_external_target: bool = False,
    metadata: Optional[Mapping[str, Any]] = None,
    discovery_max_candidates: Optional[int] = 8,
    max_candidates: Optional[int] = None,
    include_seed: bool = True,
    factory: Optional[bool] = None,
    min_turns: int = 1,
    max_turns: int = 1,
    manifest_path: str | Path | None = None,
    result_name: Optional[str] = None,
    no_eval: Optional[bool] = None,
    dry_run: Optional[bool] = None,
    include_manifest: bool = True,
) -> dict[str, Any]:
    """Optimize, promote, and run a local framework adapter in one SDK call."""

    manifest = await asyncio.to_thread(
        build_framework_run_manifest_from_local_adapter,
        name=name,
        framework=framework,
        target=target,
        adapter_candidates=adapter_candidates,
        agent=agent,
        agent_factory=agent_factory,
        cases=cases,
        target_base_dir=target_base_dir,
        target_factory=target_factory,
        method_candidates=method_candidates,
        input_mode_candidates=input_mode_candidates,
        required_env=required_env,
        scenario=scenario,
        framework_trace=framework_trace,
        evaluation_config=evaluation_config,
        auto_evaluation_config=auto_evaluation_config,
        threshold=threshold,
        trace_runtime=trace_runtime,
        allow_external_target=allow_external_target,
        metadata=metadata,
        discovery_max_candidates=discovery_max_candidates,
        max_candidates=max_candidates,
        include_seed=include_seed,
        factory=factory,
        min_turns=min_turns,
        max_turns=max_turns,
    )
    selected_manifest_path = (
        Path(manifest_path).expanduser()
        if manifest_path is not None
        else Path(target_base_dir).expanduser() / f"{name}.manifest.json"
    )

    from . import simulate as _agent_simulate

    result = await _agent_simulate.run_manifest(
        manifest,
        manifest_path=selected_manifest_path,
        name=result_name,
        threshold=threshold,
        no_eval=no_eval,
        dry_run=dry_run,
    )
    payload = copy.deepcopy(dict(result))
    summary = _plain_mapping(payload.get("summary"))
    summary["framework_adapter_direct_run"] = True
    summary["framework_adapter_manifest_name"] = manifest.get("name")
    summary["framework_adapter_manifest_target"] = _plain_mapping(
        manifest.get("agent")
    ).get("target")
    payload["summary"] = summary
    payload["metadata"] = {
        **_plain_mapping(payload.get("metadata")),
        "source": "fi.alk.optimize.run_framework_adapter_from_local_adapter",
        "framework_adapter_direct_run": True,
    }
    if include_manifest:
        payload["framework_adapter_run_manifest"] = copy.deepcopy(manifest)
    return payload


def build_framework_run_manifest_from_probe_optimization(
    optimization_result: Mapping[str, Any],
    *,
    name: Optional[str] = None,
    target: Optional[str] = None,
    required_env: Sequence[str] = (),
    scenario: Optional[Mapping[str, Any]] = None,
    framework_trace: Optional[Mapping[str, Any]] = None,
    evaluation_config: Optional[Mapping[str, Any]] = None,
    auto_evaluation_config: bool = False,
    threshold: float = 0.9,
    metadata: Optional[Mapping[str, Any]] = None,
    factory: Optional[bool] = None,
    min_turns: int = 1,
    max_turns: int = 1,
) -> dict[str, Any]:
    """Promote a verified adapter-probe optimization into a run manifest."""

    payload = _plain_mapping(optimization_result)
    if not payload:
        raise ValueError("optimization_result must be a mapping")
    if payload.get("kind") and payload.get("kind") != AGENT_LEARNING_OPTIMIZATION_KIND:
        raise ValueError("optimization_result must be an agent-learning optimization")

    optimization = _plain_mapping(payload.get("optimization"))
    if not optimization:
        raise ValueError("optimization_result must contain optimization")
    best_config = _plain_mapping(optimization.get("best_config"))
    adapter = _plain_mapping(best_config.get("adapter"))
    if not adapter:
        raise ValueError("optimization.best_config.adapter is required")

    summary = _plain_mapping(payload.get("summary"))
    source_manifest = _plain_mapping(optimization.get("source_manifest"))
    source_metadata = _plain_mapping(source_manifest.get("metadata"))
    proof = _plain_mapping(
        payload.get("framework_adapter_probe_proof")
        or optimization.get("framework_adapter_probe_proof")
    )
    if proof.get("kind") != AGENT_LEARNING_FRAMEWORK_ADAPTER_PROBE_PROOF_KIND:
        raise ValueError("framework_adapter_probe_proof is required")
    if proof.get("passed") is not True or proof.get("status") != "passed":
        raise ValueError("framework_adapter_probe_proof must be passed")

    selected_history = _selected_optimization_history(payload, optimization)
    selected_report = _plain_mapping(selected_history.get("report"))
    if selected_report and selected_report.get("status") != "passed":
        raise ValueError("selected framework adapter probe report must be passed")
    proof_evidence = _plain_mapping(proof.get("evidence"))
    selected_report_summary = _plain_mapping(
        selected_report.get("summary")
        or proof_evidence.get("selected_report_summary")
    )
    selected_contract = _plain_mapping(
        selected_report.get("contract")
        or proof_evidence.get("framework_adapter_contract")
    )
    discovery = _plain_mapping(
        payload.get("framework_adapter_discovery")
        or optimization.get("framework_adapter_discovery")
        or proof_evidence.get("framework_adapter_discovery")
    )
    discovery_summary = _plain_mapping(discovery.get("summary"))

    framework = str(
        best_config.get("framework")
        or summary.get("framework")
        or proof.get("framework")
        or selected_report.get("framework")
        or source_metadata.get("framework")
        or ""
    )
    selected_target = str(
        target
        or adapter.get("target")
        or best_config.get("target")
        or source_metadata.get("target")
        or ""
    )
    if not framework:
        raise ValueError("selected framework is required")
    if not selected_target:
        raise ValueError("selected adapter target is required")

    method = adapter.get("method") or proof.get("method") or selected_report.get("method")
    input_mode = (
        adapter.get("input_mode")
        or proof.get("input_mode")
        or selected_report.get("input_mode")
    )
    input_key = (
        adapter.get("input_key")
        or proof.get("input_key")
        or selected_report.get("input_key")
        or selected_contract.get("input_key")
    )
    input_kwargs = _plain_mapping(adapter.get("input_kwargs"))
    trace_runtime = bool(
        adapter.get(
            "trace_runtime",
            selected_contract.get("trace_runtime", True),
        )
    )
    selected_factory = (
        bool(factory)
        if factory is not None
        else bool(adapter.get("factory", best_config.get("factory", True)))
    )
    adapter_metadata = _plain_mapping(adapter.get("metadata"))
    merged_metadata = {
        **copy.deepcopy(adapter_metadata),
        **copy.deepcopy(dict(metadata or {})),
        "source": (
            "fi.alk.optimize."
            "build_framework_run_manifest_from_probe_optimization"
        ),
        "promoted_from_framework_adapter_probe": True,
        "probe_optimization_name": payload.get("name"),
        "probe_selected_candidate_id": (
            optimization.get("best_candidate_id")
            or summary.get("best_candidate_id")
            or proof.get("selected_candidate_id")
        ),
        "framework_adapter_probe_proof": copy.deepcopy(proof),
        "framework_adapter_probe_contract": copy.deepcopy(selected_contract),
        "framework_adapter_probe_report_summary": copy.deepcopy(
            selected_report_summary
        ),
        "adapter_candidate_source": (
            summary.get("adapter_candidate_source")
            or source_metadata.get("adapter_candidate_source")
            or "explicit"
        ),
        "framework_adapter_discovery_used": bool(discovery),
        "framework_adapter_discovery": copy.deepcopy(discovery),
        "framework_adapter_discovery_summary": copy.deepcopy(discovery_summary),
    }
    selected_evaluation_config = (
        copy.deepcopy(dict(evaluation_config))
        if evaluation_config is not None
        else (
            build_framework_adapter_probe_evaluation_config(payload)
            if auto_evaluation_config
            else None
        )
    )

    from . import simulate as _agent_simulate

    manifest = _agent_simulate.build_framework_run_manifest(
        name=str(name or f"{payload.get('name') or 'framework-adapter-probe'}-run"),
        framework=framework,
        target=selected_target,
        required_env=required_env,
        method=str(method) if method else None,
        input_mode=str(input_mode) if input_mode else None,
        input_key=str(input_key) if input_key else None,
        input_kwargs=input_kwargs or None,
        factory=selected_factory,
        trace_runtime=trace_runtime,
        metadata=merged_metadata,
        scenario=scenario,
        framework_trace=framework_trace,
        min_turns=min_turns,
        max_turns=max_turns,
        evaluation_enabled=selected_evaluation_config is not None,
        output_key=str(adapter["output_key"]) if adapter.get("output_key") else None,
        system_prompt=(
            str(adapter["system_prompt"]) if adapter.get("system_prompt") else None
        ),
    )
    manifest["metadata"] = {
        **_plain_mapping(manifest.get("metadata")),
        "promoted_from_framework_adapter_probe": True,
        "probe_optimization_name": payload.get("name"),
        "probe_selected_candidate_id": merged_metadata[
            "probe_selected_candidate_id"
        ],
        "framework_adapter_probe_proof_status": proof.get("status"),
        "adapter_candidate_source": merged_metadata["adapter_candidate_source"],
        "framework_adapter_discovery_used": bool(discovery),
        "framework_adapter_discovery_status": discovery.get("status"),
    }
    if selected_evaluation_config is not None:
        manifest["evaluation"] = {
            "enabled": True,
            "agent_report": {
                "threshold": float(threshold),
                "config": selected_evaluation_config,
            },
        }
    return manifest


def build_framework_adapter_probe_evaluation_config(
    optimization_result: Mapping[str, Any],
    *,
    task_description: Optional[str] = None,
    expected_result: Optional[str] = None,
    required_tools: Optional[Sequence[str]] = None,
    success_criteria: Optional[Sequence[str]] = None,
) -> dict[str, Any]:
    """Build an agent-report config from a verified adapter-probe optimization."""

    payload = _plain_mapping(optimization_result)
    if not payload:
        raise ValueError("optimization_result must be a mapping")
    optimization = _plain_mapping(payload.get("optimization"))
    best_config = _plain_mapping(optimization.get("best_config"))
    adapter = _plain_mapping(best_config.get("adapter"))
    proof = _plain_mapping(
        payload.get("framework_adapter_probe_proof")
        or optimization.get("framework_adapter_probe_proof")
    )
    if proof.get("kind") != AGENT_LEARNING_FRAMEWORK_ADAPTER_PROBE_PROOF_KIND:
        raise ValueError("framework_adapter_probe_proof is required")
    if proof.get("passed") is not True or proof.get("status") != "passed":
        raise ValueError("framework_adapter_probe_proof must be passed")

    selected_history = _selected_optimization_history(payload, optimization)
    selected_report = _plain_mapping(selected_history.get("report"))
    proof_evidence = _plain_mapping(proof.get("evidence"))
    contract = _plain_mapping(
        selected_report.get("contract")
        or proof_evidence.get("framework_adapter_contract")
    )
    selected_report_summary = _plain_mapping(
        selected_report.get("summary")
        or proof_evidence.get("selected_report_summary")
    )
    framework = str(
        contract.get("framework")
        or selected_report.get("framework")
        or proof.get("framework")
        or best_config.get("framework")
        or "custom"
    )
    method = str(
        adapter.get("method")
        or proof.get("method")
        or selected_report.get("method")
        or contract.get("method")
        or "auto"
    )
    input_mode = str(
        adapter.get("input_mode")
        or proof.get("input_mode")
        or selected_report.get("input_mode")
        or contract.get("input_mode")
        or "auto"
    )
    input_key = str(
        adapter.get("input_key")
        or proof.get("input_key")
        or selected_report.get("input_key")
        or contract.get("input_key")
        or next(iter(_plain_list(selected_report_summary.get("input_keys"))), "")
        or ""
    )
    input_kwargs_keys = _unique_strings(
        [
            *[
                str(key)
                for key in _plain_mapping(adapter.get("input_kwargs")).keys()
                if str(key)
            ],
            *[
                str(key)
                for key in _plain_list(proof.get("input_kwargs_keys"))
                if str(key)
            ],
            *[
                str(key)
                for key in _plain_list(contract.get("input_kwargs_keys"))
                if str(key)
            ],
            *[
                str(key)
                for key in _plain_list(selected_report_summary.get("input_kwargs_keys"))
                if str(key)
            ],
        ]
    )
    tool_names = _unique_strings(
        [
            *list(required_tools or []),
            *_framework_probe_response_values(selected_report, "tool_names"),
        ]
    )
    state_keys = _unique_strings(
        _framework_probe_response_values(selected_report, "state_keys")
    )
    event_types = _unique_strings(
        _framework_probe_response_values(selected_report, "event_types")
    )
    artifact_types = _framework_probe_output_artifact_types(selected_report)
    runtime_state_keys = [
        key
        for key in state_keys
        if key not in {"framework_runtime", "streaming_trace"}
    ]
    streaming_trace_signals = _unique_strings(
        _framework_probe_response_values(selected_report, "streaming_trace_signals")
    )
    streaming_observed = (
        _as_int(selected_report_summary.get("streaming_trace_count")) > 0
        or "streaming_trace" in state_keys
        or bool(streaming_trace_signals)
    )
    if streaming_observed and not streaming_trace_signals:
        streaming_trace_signals = ["chunk"]
    realtime_trace_summary = _framework_probe_first_response_mapping(
        selected_report,
        "realtime_trace_summary",
    )
    realtime_trace_observed = (
        "realtime_trace" in state_keys
        or bool(realtime_trace_summary)
    )
    realtime_trace_requirements = (
        _framework_probe_realtime_trace_requirements(
            framework,
            realtime_trace_summary,
        )
        if realtime_trace_observed
        else {}
    )
    framework_trace_summary = _framework_probe_first_response_mapping(
        selected_report,
        "framework_trace_summary",
    )
    framework_trace_observed = (
        "framework_trace" in state_keys
        or bool(framework_trace_summary)
    )
    required_framework_trace = (
        _framework_probe_trace_requirements(framework, framework_trace_summary)
        if framework_trace_observed
        else []
    )
    framework_trace_quality = (
        _framework_probe_trace_quality_requirements(
            framework,
            framework_trace_summary,
        )
        if framework_trace_observed
        else {}
    )
    message_history_summary = _framework_probe_first_response_mapping(
        selected_report,
        "message_history_summary",
    )
    framework_handoff_summary = _framework_probe_first_response_mapping(
        selected_report,
        "framework_handoff_summary",
    )
    framework_transcript_observed = (
        "message_history" in state_keys
        or "framework_handoffs" in state_keys
        or bool(message_history_summary)
        or bool(framework_handoff_summary)
    )
    framework_transcript_quality = (
        _framework_probe_transcript_quality_requirements(
            framework,
            message_history_summary,
            framework_handoff_summary,
        )
        if framework_transcript_observed
        else {}
    )
    orchestration_trace_summary = _framework_probe_first_response_mapping(
        selected_report,
        "orchestration_trace_summary",
    )
    orchestration_trace_observed = (
        "orchestration_trace" in state_keys
        or bool(orchestration_trace_summary)
    )
    orchestration_requirements = (
        _framework_probe_orchestration_requirements(
            framework,
            orchestration_trace_summary,
        )
        if orchestration_trace_observed
        else {}
    )
    workflow_trace_summary = _framework_probe_first_response_mapping(
        selected_report,
        "workflow_trace_summary",
    )
    workflow_trace_observed = (
        "workflow_trace" in state_keys
        or any(str(event).startswith("workflow_") for event in event_types)
        or bool(workflow_trace_summary)
    )
    workflow_requirements = (
        _framework_probe_workflow_requirements(
            framework,
            workflow_trace_summary,
        )
        if workflow_trace_observed
        else {}
    )
    mcp_tool_session_summary = _framework_probe_first_response_mapping(
        selected_report,
        "mcp_tool_session_summary",
    )
    mcp_tool_session_observed = (
        "mcp_tool_session" in state_keys
        or bool(mcp_tool_session_summary)
    )
    mcp_tool_session_requirements = (
        _framework_probe_mcp_tool_session_requirements(
            framework,
            mcp_tool_session_summary,
        )
        if mcp_tool_session_observed
        else {}
    )
    a2a_protocol_summary = _framework_probe_first_response_mapping(
        selected_report,
        "a2a_protocol_summary",
    )
    a2a_protocol_observed = (
        "a2a_protocol_trace" in state_keys
        or bool(a2a_protocol_summary)
    )
    a2a_protocol_requirements = (
        _framework_probe_a2a_protocol_requirements(
            framework,
            a2a_protocol_summary,
        )
        if a2a_protocol_observed
        else {}
    )
    openenv_summary = _framework_probe_first_response_mapping(
        selected_report,
        "openenv_summary",
    )
    openenv_observed = (
        "openenv" in state_keys
        or any("openenv" in str(event) for event in event_types)
        or bool(openenv_summary)
    )
    openenv_requirements = (
        _framework_probe_openenv_requirements(framework, openenv_summary)
        if openenv_observed
        else {}
    )
    framework_memory_summary = _framework_probe_first_response_mapping(
        selected_report,
        "framework_memory_summary",
    )
    retrieval_memory_summary = _framework_probe_first_response_mapping(
        selected_report,
        "retrieval_memory_summary",
    )
    agent_memory_lineage_summary = _framework_probe_first_response_mapping(
        selected_report,
        "agent_memory_lineage_summary",
    )
    memory_trace_observed = (
        "framework_memory" in state_keys
        or "retrieval_memory" in state_keys
        or "agent_memory_lineage" in state_keys
        or any(str(event).startswith("framework_memory") for event in event_types)
        or bool(framework_memory_summary)
        or bool(retrieval_memory_summary)
        or bool(agent_memory_lineage_summary)
    )
    memory_trace_requirements = (
        _framework_probe_memory_requirements(
            framework,
            framework_memory_summary,
            retrieval_memory_summary,
            agent_memory_lineage_summary,
        )
        if memory_trace_observed
        else {}
    )
    browser_cua_summary = _framework_probe_first_response_mapping(
        selected_report,
        "browser_cua_summary",
    )
    browser_cua_observed = (
        "browser_cua" in state_keys
        or any(str(event).startswith("browser_") for event in event_types)
        or "environment_injection" in event_types
        or bool(browser_cua_summary)
    )
    browser_cua_requirements = (
        _framework_probe_browser_cua_requirements(
            framework,
            browser_cua_summary,
        )
        if browser_cua_observed
        else {}
    )
    lifecycle_summary = _framework_probe_first_response_mapping(
        selected_report,
        "framework_lifecycle_summary",
    )
    lifecycle_observed = (
        "framework_lifecycle_trace" in state_keys
        or bool(lifecycle_summary)
    )
    lifecycle_requirements = (
        _framework_probe_lifecycle_requirements(framework, lifecycle_summary)
        if lifecycle_observed
        else {}
    )
    trust_boundary_summary = _framework_probe_first_response_mapping(
        selected_report,
        "agent_trust_boundary_summary",
    )
    control_plane_summary = _framework_probe_first_response_mapping(
        selected_report,
        "agent_control_plane_summary",
    )
    agent_control_plane_observed = (
        "agent_trust_boundary_model" in state_keys
        or "agent_control_plane" in state_keys
        or bool(trust_boundary_summary)
        or bool(control_plane_summary)
    )
    agent_control_plane_requirements = (
        _framework_probe_agent_control_plane_requirements(
            framework,
            trust_boundary_summary,
            control_plane_summary,
        )
        if agent_control_plane_observed
        else {}
    )
    required_signals = _unique_strings(
        [
            "method",
            "input",
            "output",
            "metadata",
            *(["state"] if runtime_state_keys else []),
            *(["streaming"] if streaming_observed else []),
            *(["realtime"] if realtime_trace_observed else []),
            *(["orchestration"] if orchestration_trace_observed else []),
            *(["workflow"] if workflow_trace_observed else []),
            *(["protocol"] if mcp_tool_session_observed or a2a_protocol_observed else []),
            *(["openenv"] if openenv_observed else []),
            *(["memory"] if memory_trace_observed else []),
            *(["browser"] if browser_cua_observed else []),
            *(["control_plane"] if agent_control_plane_observed else []),
            *(["tool"] if tool_names else []),
            *(["event"] if event_types else []),
            *(["artifact"] if artifact_types else []),
        ]
    )
    criteria = _unique_strings(
        list(success_criteria or [])
        or [
            f"{method} runtime evidence",
            "framework adapter contract quality",
            *(["typed state evidence"] if runtime_state_keys else []),
            *(["streaming trace evidence"] if streaming_observed else []),
            *(["realtime trace evidence"] if realtime_trace_observed else []),
            *(["framework trace evidence"] if framework_trace_observed else []),
            *(["framework transcript evidence"] if framework_transcript_observed else []),
            *(["handoff transcript evidence"] if framework_handoff_summary else []),
            *(["orchestration trace evidence"] if orchestration_trace_observed else []),
            *(["workflow graph evidence"] if workflow_trace_observed else []),
            *(["MCP tool session evidence"] if mcp_tool_session_observed else []),
            *(["A2A protocol evidence"] if a2a_protocol_observed else []),
            *(["OpenEnv environment replay evidence"] if openenv_observed else []),
            *(["memory lineage evidence"] if memory_trace_observed else []),
            *(["browser/CUA evidence"] if browser_cua_observed else []),
            *(
                ["agent trust-boundary and control-plane evidence"]
                if agent_control_plane_observed
                else []
            ),
            *(["tool evidence"] if tool_names else []),
            *(["event evidence"] if event_types else []),
            *(["artifact evidence"] if artifact_types else []),
        ]
    )
    contract_capabilities = _unique_strings(contract.get("capabilities"))
    required_capabilities = [
        capability
        for capability in [
            "messages",
            "tool_calls",
            "runtime_trace",
            "structured_input",
            "streaming_trace",
        ]
        if capability in contract_capabilities
    ]
    if not required_capabilities:
        required_capabilities = ["messages", "tool_calls", "runtime_trace"]

    runtime_contract: dict[str, Any] = {
        "framework": framework,
        "method": method,
        "input_mode": input_mode,
        "required_signals": required_signals,
        "max_error_count": 0,
        "min_invocation_count": max(
            _as_int(selected_report_summary.get("runtime_trace_count")),
            1,
        ),
    }
    if tool_names:
        runtime_contract["required_tools"] = tool_names
    if artifact_types:
        runtime_contract["required_artifact_types"] = artifact_types
    if input_key:
        runtime_contract["input_key"] = input_key
        runtime_contract["call_style"] = "keyword"
    if input_kwargs_keys:
        runtime_contract["required_input_kwargs"] = input_kwargs_keys
    if runtime_state_keys:
        runtime_contract["required_state_keys"] = runtime_state_keys
    if streaming_observed:
        runtime_contract["require_streaming"] = True

    contract_quality: dict[str, Any] = {
        "kind": "agent-learning.framework-adapter-contract.v1",
        "framework": framework,
        "method": method,
        "input_mode": input_mode,
        "require_trace_runtime": True,
        "require_local_executable_fixture": True,
        "require_no_external_service": True,
        "require_target": True,
        "required_schema_sections": ["input", "output"],
        "required_lifecycle_hooks": _unique_strings(
            contract.get("lifecycle_hooks")
        )
        or ["setup", "invoke", "observe", "teardown"],
        "required_capabilities": required_capabilities,
        "required_evidence_requirements": _unique_strings(
            contract.get("evidence_requirements")
        )
        or [
            "framework_runtime",
            "framework_trace",
            "tool_calls",
            "adapter_conformance",
            "metric_evidence",
        ],
    }
    callable_signature = _plain_mapping(contract.get("callable_signature"))
    call_contract_count = max(
        _as_int(selected_report_summary.get("call_contract_count"))
        or _as_int(selected_report_summary.get("runtime_trace_count"))
        or 1,
        1,
    )
    observed_io_contract_count = max(
        _as_int(selected_report_summary.get("observed_io_contract_count"))
        or _as_int(selected_report_summary.get("runtime_trace_count"))
        or 1,
        1,
    )
    call_styles = _unique_strings(selected_report_summary.get("call_styles"))
    input_types = _unique_strings(selected_report_summary.get("input_types"))
    output_types = _unique_strings(selected_report_summary.get("output_types"))
    call_contract_quality: dict[str, Any] = {
        "kind": "agent-learning.framework-adapter-call-contract.v1",
        "framework": framework,
        "method": method,
        "input_mode": input_mode,
        "require_signature": True,
        "require_signature_inspectable": True,
        "require_signature_bound": True,
        "max_error_count": 0,
        "min_contract_count": call_contract_count,
    }
    if input_key:
        call_contract_quality["input_key"] = input_key
    if call_styles:
        call_contract_quality["required_call_styles"] = call_styles
    elif input_key:
        call_contract_quality["call_style"] = "keyword"
    if input_kwargs_keys:
        call_contract_quality["required_input_kwargs"] = input_kwargs_keys
    parameter_names = _unique_strings(callable_signature.get("parameter_names"))
    if parameter_names:
        call_contract_quality["required_parameter_names"] = parameter_names
    keyword_only_parameters = _unique_strings(
        callable_signature.get("keyword_only_parameters")
    )
    if keyword_only_parameters:
        call_contract_quality["required_keyword_only_parameters"] = (
            keyword_only_parameters
        )

    observed_io_quality: dict[str, Any] = {
        "kind": "agent-learning.framework-adapter-observed-io-contract.v1",
        "framework": framework,
        "method": method,
        "input_mode": input_mode,
        "require_signature_bound": True,
        "max_error_count": 0,
        "min_contract_count": observed_io_contract_count,
        "min_invocation_count": observed_io_contract_count,
    }
    if call_styles:
        observed_io_quality["required_call_styles"] = call_styles
    elif input_key:
        observed_io_quality["required_call_styles"] = ["keyword"]
    if input_key:
        observed_io_quality["required_input_keys"] = [input_key]
    if input_kwargs_keys:
        observed_io_quality["required_input_kwargs"] = input_kwargs_keys
    if input_types:
        observed_io_quality["required_input_types"] = input_types
    if output_types:
        observed_io_quality["required_output_types"] = output_types
    if tool_names:
        observed_io_quality["required_output_tool_names"] = tool_names
    observed_io_event_types = [
        event_type
        for event_type in event_types
        if str(event_type).lower() != "framework_runtime"
    ]
    if observed_io_event_types:
        observed_io_quality["required_output_event_types"] = observed_io_event_types
    if artifact_types:
        observed_io_quality["required_output_artifact_types"] = artifact_types
    if _framework_probe_response_content_observed(selected_report):
        observed_io_quality["require_content_observed"] = True

    metric_weights = {
        "framework_adapter_contract_quality": 8.0,
        "framework_adapter_call_contract_quality": 8.0,
        "framework_adapter_observed_io_quality": 8.0,
        "framework_runtime_contract": 10.0,
        "task_completion": 1.0,
    }
    if tool_names:
        metric_weights["tool_selection_accuracy"] = 4.0
    if streaming_observed:
        metric_weights["streaming_trace_coverage"] = 4.0
    if realtime_trace_observed:
        metric_weights["realtime_trace_coverage"] = 4.0
        metric_weights["realtime_trace_quality"] = 4.0
    if framework_trace_observed:
        metric_weights["framework_trace_coverage"] = 4.0
        metric_weights["framework_trace_quality"] = 4.0
    if framework_transcript_observed:
        metric_weights["framework_transcript_quality"] = 4.0
    if orchestration_trace_observed:
        metric_weights["orchestration_trace_coverage"] = 4.0
        metric_weights["orchestration_flow_quality"] = 4.0
    if workflow_trace_observed:
        metric_weights["workflow_trace_coverage"] = 4.0
        metric_weights["workflow_graph_quality"] = 4.0
    if mcp_tool_session_observed:
        metric_weights["mcp_tool_session_coverage"] = 4.0
        metric_weights["mcp_tool_session_quality"] = 4.0
    if a2a_protocol_observed:
        metric_weights["a2a_protocol_coverage"] = 4.0
        metric_weights["a2a_protocol_quality"] = 4.0
    if openenv_observed:
        metric_weights["openenv_coverage"] = 4.0
        metric_weights["openenv_quality"] = 4.0
    if memory_trace_observed:
        metric_weights["agent_memory_lineage_coverage"] = 4.0
        metric_weights["agent_memory_lineage_quality"] = 4.0
        metric_weights["retrieval_memory_attribution"] = 4.0
    if browser_cua_observed:
        metric_weights["browser_action_safety"] = 4.0
        metric_weights["browser_action_outcome"] = 4.0
        metric_weights["browser_grounding_quality"] = 4.0
        metric_weights["browser_mutation_resilience"] = 4.0
        metric_weights["browser_trace_coverage"] = 4.0
    if lifecycle_observed:
        metric_weights["framework_lifecycle_coverage"] = 4.0
        metric_weights["framework_lifecycle_quality"] = 4.0
    if agent_control_plane_observed:
        metric_weights["agent_trust_boundary_coverage"] = 4.0
        metric_weights["agent_trust_boundary_quality"] = 4.0
        metric_weights["agent_control_plane_coverage"] = 4.0
        metric_weights["agent_control_plane_quality"] = 4.0

    config = {
        "task_description": task_description
        or f"Validate the promoted {framework} framework adapter.",
        "expected_result": expected_result
        or (
            f"The selected {method}/{input_mode} adapter emits local framework "
            "runtime evidence."
        ),
        "required_tools": tool_names,
        "available_tools": tool_names,
        "required_events": event_types,
        "required_artifact_types": artifact_types,
        "success_criteria": criteria,
        "required_framework_runtime": [
            "framework_runtime",
            "method",
            "input",
            "output",
            "metadata",
            *(["state"] if runtime_state_keys else []),
            *(["streaming"] if streaming_observed else []),
            *(["realtime"] if realtime_trace_observed else []),
            *(["orchestration"] if orchestration_trace_observed else []),
            *(["workflow"] if workflow_trace_observed else []),
            *(["protocol"] if mcp_tool_session_observed or a2a_protocol_observed else []),
            *(["openenv"] if openenv_observed else []),
            *(["memory"] if memory_trace_observed else []),
            *(["browser"] if browser_cua_observed else []),
            *(["control_plane"] if agent_control_plane_observed else []),
            *(["tool"] if tool_names else []),
            *(["event"] if event_types else []),
            *(["artifact"] if artifact_types else []),
        ],
        "framework_runtime_contract": runtime_contract,
        "framework_adapter_call_contract_quality": call_contract_quality,
        "framework_adapter_observed_io_quality": observed_io_quality,
        "framework_adapter_contract_quality": contract_quality,
        "metric_weights": metric_weights,
    }
    if streaming_observed:
        config["required_streaming_trace"] = streaming_trace_signals
    if realtime_trace_observed:
        config["required_realtime_trace"] = realtime_trace_requirements[
            "required_realtime_trace"
        ]
        config["realtime_trace_quality"] = realtime_trace_requirements[
            "realtime_trace_quality"
        ]
    if framework_trace_observed:
        config["required_framework_trace"] = required_framework_trace
        config["framework_trace_quality"] = framework_trace_quality
    if framework_transcript_observed:
        config["framework_transcript_quality"] = framework_transcript_quality
    if orchestration_trace_observed:
        config["required_orchestration_trace"] = orchestration_requirements[
            "required_orchestration_trace"
        ]
        config["orchestration_trace_quality"] = orchestration_requirements[
            "orchestration_trace_quality"
        ]
    if workflow_trace_observed:
        config["required_workflow_trace"] = workflow_requirements[
            "required_workflow_trace"
        ]
        config["workflow_trace_quality"] = workflow_requirements[
            "workflow_trace_quality"
        ]
    if mcp_tool_session_observed:
        config["required_mcp_tool_session"] = mcp_tool_session_requirements[
            "required_mcp_tool_session"
        ]
        config["mcp_tool_session_quality"] = mcp_tool_session_requirements[
            "mcp_tool_session_quality"
        ]
    if a2a_protocol_observed:
        config["required_a2a_protocol"] = a2a_protocol_requirements[
            "required_a2a_protocol"
        ]
        config["a2a_protocol_quality"] = a2a_protocol_requirements[
            "a2a_protocol_quality"
        ]
    if openenv_observed:
        config["required_openenv"] = openenv_requirements["required_openenv"]
        config["openenv_quality"] = openenv_requirements["openenv_quality"]
    if memory_trace_observed:
        config["required_agent_memory_lineage"] = memory_trace_requirements[
            "required_agent_memory_lineage"
        ]
        config["agent_memory_lineage_quality"] = memory_trace_requirements[
            "agent_memory_lineage_quality"
        ]
        config["required_retrieval_memory_trace"] = memory_trace_requirements[
            "required_retrieval_memory_trace"
        ]
    if browser_cua_observed:
        config.update(browser_cua_requirements)
    if lifecycle_observed:
        config["required_framework_lifecycle"] = lifecycle_requirements[
            "required_framework_lifecycle"
        ]
        config["framework_lifecycle_quality"] = lifecycle_requirements[
            "framework_lifecycle_quality"
        ]
    if agent_control_plane_observed:
        config["required_agent_trust_boundary"] = agent_control_plane_requirements[
            "required_agent_trust_boundary"
        ]
        config["agent_trust_boundary_quality"] = agent_control_plane_requirements[
            "agent_trust_boundary_quality"
        ]
        config["required_agent_control_plane"] = agent_control_plane_requirements[
            "required_agent_control_plane"
        ]
        config["agent_control_plane_quality"] = agent_control_plane_requirements[
            "agent_control_plane_quality"
        ]
    return config


def _framework_probe_response_values(
    selected_report: Mapping[str, Any],
    key: str,
) -> list[str]:
    values: list[str] = []
    for case in _plain_list(selected_report.get("cases")):
        case_dict = _plain_mapping(case)
        response = _plain_mapping(case_dict.get("response"))
        values.extend(str(item) for item in _plain_list(response.get(key)) if str(item))
    return values


def _framework_probe_response_content_observed(
    selected_report: Mapping[str, Any],
) -> bool:
    for case in _plain_list(selected_report.get("cases")):
        case_dict = _plain_mapping(case)
        response = _plain_mapping(case_dict.get("response"))
        content = response.get("content")
        if content not in (None, "", [], {}):
            return True
        content_length = _as_int(response.get("content_length"))
        if content_length is not None and content_length > 0:
            return True
    return False


def _framework_probe_first_response_mapping(
    selected_report: Mapping[str, Any],
    key: str,
) -> dict[str, Any]:
    for case in _plain_list(selected_report.get("cases")):
        case_dict = _plain_mapping(case)
        response = _plain_mapping(case_dict.get("response"))
        value = _plain_mapping(response.get(key))
        if value:
            return value
    return {}


def _framework_probe_lifecycle_requirements(
    framework: str,
    summary: Mapping[str, Any],
) -> dict[str, Any]:
    summary = _plain_mapping(summary)
    required_lifecycle = ["framework_lifecycle", "lifecycle"]
    quality: dict[str, Any] = {
        "framework": framework,
        "min_phase_count": max(_as_int(summary.get("phase_count")), 1),
    }
    signal_checks = (
        ("session_count", "session", "required_sessions"),
        ("tool_registration_count", "tool_registration", "min_tool_registrations"),
        ("invocation_count", "invocation", "min_invocations"),
        ("streaming_event_count", "streaming", "require_streaming"),
        ("checkpoint_count", "checkpoint", "require_checkpoint"),
        ("retry_count", "retry", "require_retry"),
        ("cancellation_count", "cancellation", "require_cancellation"),
        ("resume_count", "resume", "require_resume"),
        ("cleanup_count", "cleanup", "require_cleanup"),
    )
    for summary_key, signal, quality_key in signal_checks:
        count = _as_int(summary.get(summary_key))
        if count <= 0:
            continue
        required_lifecycle.append(signal)
        if quality_key in {
            "require_streaming",
            "require_checkpoint",
            "require_retry",
            "require_cancellation",
            "require_resume",
            "require_cleanup",
        }:
            quality[quality_key] = True
        elif quality_key in {"min_tool_registrations", "min_invocations"}:
            quality[quality_key] = count
    if bool(summary.get("state_persistence")):
        required_lifecycle.append("state_persistence")
        quality["require_state_persistence"] = True
    recovered_errors = _as_int(summary.get("recovered_error_count"))
    if recovered_errors > 0:
        required_lifecycle.append("recovery")
        quality["min_recovered_errors"] = recovered_errors
    error_count = _as_int(summary.get("error_count"))
    if error_count >= 0:
        quality["max_error_count"] = error_count
    terminal_status = str(summary.get("terminal_status") or "")
    if terminal_status:
        quality["terminal_status"] = terminal_status
    return {
        "required_framework_lifecycle": _unique_strings(required_lifecycle),
        "framework_lifecycle_quality": quality,
    }


def _framework_probe_agent_control_plane_requirements(
    framework: str,
    trust_summary: Mapping[str, Any],
    control_summary: Mapping[str, Any],
) -> dict[str, Any]:
    trust_summary = _plain_mapping(trust_summary)
    control_summary = _plain_mapping(control_summary)
    trust_controls = _unique_strings(trust_summary.get("present_controls"))
    trust_categories = _unique_strings(trust_summary.get("present_categories"))
    trust_assets = _unique_strings(trust_summary.get("assets"))
    trust_tools = _unique_strings(trust_summary.get("tools"))
    trust_surfaces = _unique_strings(trust_summary.get("surfaces"))
    trust_threats = _unique_strings(
        trust_summary.get("mitigated_threats") or trust_summary.get("threats")
    )
    control_controls = _unique_strings(control_summary.get("present_controls"))
    control_categories = _unique_strings(control_summary.get("present_categories"))
    control_actions = _unique_strings(control_summary.get("actions"))
    control_budgets = _unique_strings(control_summary.get("budgets"))

    trust_quality: dict[str, Any] = {
        "framework": framework,
        "required_controls": trust_controls,
        "required_categories": trust_categories,
        "required_assets": trust_assets,
        "required_tools": trust_tools,
        "required_surfaces": trust_surfaces,
        "required_threats": trust_threats,
        "min_present_controls": max(_as_int(trust_summary.get("control_count")), 1),
        "min_control_rate": 1.0,
        "min_required_control_rate": 1.0,
        "max_missing_controls": 0,
        "max_blocked_controls": 0,
        "max_unmitigated_threats": 0,
        "max_high_risk_unmitigated_threats": _as_int(
            trust_summary.get("high_risk_unmitigated_count")
        ),
        "require_evidence": _as_int(trust_summary.get("evidence_count")) > 0,
        "forbidden_missing_controls": trust_controls,
    }
    for config_key, summary_key in (
        ("require_identity", "has_identity"),
        ("require_permissions", "has_permissions"),
        ("require_sandbox", "has_sandbox"),
        ("require_audit", "has_audit"),
        ("require_canaries", "has_canaries"),
        ("require_human_approval", "has_human_approval"),
        ("require_memory_isolation", "has_memory_isolation"),
        ("require_network_egress_controls", "has_network_egress_controls"),
        ("require_tool_allowlist", "has_tool_allowlist"),
        ("require_data_boundary", "has_data_boundary"),
        ("require_secret_handling", "has_secret_handling"),
    ):
        if trust_summary.get(summary_key):
            trust_quality[config_key] = True

    control_quality: dict[str, Any] = {
        "framework": framework,
        "required_controls": control_controls,
        "required_categories": control_categories,
        "required_actions": control_actions,
        "required_budgets": control_budgets,
        "min_present_controls": max(_as_int(control_summary.get("control_count")), 1),
        "min_control_rate": 1.0,
        "min_required_control_rate": 1.0,
        "max_missing_controls": 0,
        "max_blocked_controls": 0,
        "max_exceeded_budgets": _as_int(
            control_summary.get("exceeded_budget_count")
        ),
        "max_uncontained_incidents": _as_int(
            control_summary.get("high_risk_uncontained_count")
        ),
        "max_high_risk_uncontained_incidents": _as_int(
            control_summary.get("high_risk_uncontained_count")
        ),
        "min_approved_actions": _as_int(control_summary.get("approved_action_count")),
        "min_rollback_actions": _as_int(
            control_summary.get("rolled_back_action_count")
        ),
        "require_evidence": _as_int(control_summary.get("evidence_count")) > 0,
        "forbidden_missing_controls": control_controls,
    }
    for config_key, summary_key in (
        ("require_risk_scoring", "has_risk_scoring"),
        ("require_action_policy", "has_action_policy"),
        ("require_approval_gates", "has_approval_gates"),
        ("require_rollback", "has_rollback"),
        ("require_kill_switch", "has_kill_switch"),
        ("require_circuit_breakers", "has_circuit_breakers"),
        ("require_rate_limits", "has_rate_limits"),
        ("require_budgets", "has_budgets"),
        ("require_audit", "has_audit"),
        ("require_containment", "has_containment"),
        ("require_drift_detection", "has_drift_detection"),
    ):
        if control_summary.get(summary_key):
            control_quality[config_key] = True

    return {
        "required_agent_trust_boundary": _unique_strings(
            [
                "agent_trust_boundary",
                "trust_boundary",
                "threat_model",
                *trust_controls,
                *trust_categories,
                *trust_assets,
                *trust_tools,
                *trust_surfaces,
                *trust_threats,
                *_plain_list(trust_summary.get("signals")),
            ]
        ),
        "agent_trust_boundary_quality": {
            key: value
            for key, value in trust_quality.items()
            if value not in (None, "", [], {})
        },
        "required_agent_control_plane": _unique_strings(
            [
                "agent_control_plane",
                "control_plane",
                "runtime_governance",
                *control_controls,
                *control_categories,
                *control_actions,
                *control_budgets,
                *_plain_list(control_summary.get("signals")),
            ]
        ),
        "agent_control_plane_quality": {
            key: value
            for key, value in control_quality.items()
            if value not in (None, "", [], {})
        },
    }


def _framework_probe_realtime_trace_requirements(
    framework: str,
    summary: Mapping[str, Any],
) -> dict[str, Any]:
    summary = _plain_mapping(summary)
    required = ["realtime_trace", "trace"]
    required.extend(_plain_list(summary.get("signals")))
    signal_checks = (
        ("frame_count", "frame"),
        ("event_count", "event"),
        ("tool_call_count", "tool_call"),
        ("tool_response_count", "tool_response"),
        ("transcript_count", "transcript"),
        ("audio_frame_count", "audio_frame"),
        ("lifecycle_event_count", "lifecycle"),
        ("interruption_count", "interruption"),
        ("error_count", "error"),
        ("completion_count", "completion"),
    )
    for summary_key, signal in signal_checks:
        if _as_int(summary.get(summary_key)) > 0:
            required.append(signal)
            if signal in {"tool_call", "tool_response"}:
                required.append("tool")
    if _plain_list(summary.get("frame_types")):
        required.append("frame_type")
    if _plain_list(summary.get("event_types")):
        required.append("event_type")
    for category in _plain_list(summary.get("categories")):
        category_key = str(category).strip().lower().replace("-", "_").replace(" ", "_")
        required.append(f"{category_key}_frame" if category_key != "event" else "event")
    for direction in _plain_list(summary.get("directions")):
        required.append(str(direction))
    for modality in _plain_list(summary.get("modalities")):
        required.append(str(modality))

    quality: dict[str, Any] = {"framework": framework}
    tool_names = _unique_strings(summary.get("tool_names"))
    if tool_names:
        quality["required_tools"] = tool_names
    frame_types = _unique_strings(summary.get("frame_types"))
    if frame_types:
        quality["required_frame_types"] = frame_types
    event_types = _unique_strings(summary.get("event_types"))
    if event_types:
        quality["required_event_types"] = event_types
    categories = _unique_strings(summary.get("categories"))
    if categories:
        quality["required_categories"] = categories
    directions = _unique_strings(summary.get("directions"))
    if directions:
        quality["required_directions"] = directions
    modalities = _unique_strings(summary.get("modalities"))
    if modalities:
        quality["required_modalities"] = modalities
    signals = _unique_strings(summary.get("signals"))
    if signals:
        quality["required_signals"] = signals
    for summary_key, quality_key in (
        ("frame_count", "min_frame_count"),
        ("event_count", "min_event_count"),
        ("tool_call_count", "min_tool_call_count"),
        ("tool_response_count", "min_tool_response_count"),
        ("transcript_count", "min_transcript_count"),
        ("audio_frame_count", "min_audio_frame_count"),
        ("lifecycle_event_count", "min_lifecycle_event_count"),
        ("completion_count", "min_completion_count"),
    ):
        count = _as_int(summary.get(summary_key))
        if count > 0:
            quality[quality_key] = count
    if _as_int(summary.get("completion_count")) > 0:
        quality["require_completion"] = True
    interruption_count = _as_int(summary.get("interruption_count"))
    if interruption_count >= 0:
        quality["max_interruption_count"] = interruption_count
    error_count = _as_int(summary.get("error_count"))
    if error_count >= 0:
        quality["max_error_count"] = error_count
    return {
        "required_realtime_trace": _unique_strings(
            str(item) for item in required if str(item)
        ),
        "realtime_trace_quality": quality,
    }


def _framework_probe_memory_requirements(
    framework: str,
    framework_summary: Mapping[str, Any],
    retrieval_summary: Mapping[str, Any],
    lineage_summary: Mapping[str, Any],
) -> dict[str, Any]:
    framework_summary = _plain_mapping(framework_summary)
    retrieval_summary = _plain_mapping(retrieval_summary)
    lineage_summary = _plain_mapping(lineage_summary)

    operation_types = _unique_strings(
        [
            *_plain_list(framework_summary.get("operation_types")),
            *_plain_list(lineage_summary.get("operation_types")),
        ]
    )
    policy_keys = _unique_strings(
        [
            *_plain_list(framework_summary.get("policy_keys")),
            *_plain_list(lineage_summary.get("policy_keys")),
        ]
    )
    required_lineage = [
        "agent_memory_lineage",
        "memory_lineage",
        "memory",
        "provenance",
    ]
    lineage_checks = (
        ("has_target", "target"),
        ("has_stores", "store"),
        ("has_memory_records", "memory_record"),
        ("has_operations", "operation"),
        ("has_lineage", "lineage"),
        ("has_source_attribution", "source_attribution"),
        ("has_tenant_isolation", "tenant_isolation"),
        ("has_audit", "audit"),
        ("has_retention_policy", "retention_policy"),
        ("has_deletion_policy", "deletion_policy"),
        ("has_redaction", "redaction"),
        ("has_canaries", "canary"),
        ("has_observability", "observability"),
        ("has_artifacts", "artifact"),
    )
    for flag, signal in lineage_checks:
        if lineage_summary.get(flag):
            required_lineage.append(signal)
    for operation_type in operation_types:
        required_lineage.extend([operation_type, f"{operation_type}_operation"])
    required_lineage.extend(policy_keys)

    quality: dict[str, Any] = {"framework": framework}
    count_checks = (
        ("store_count", "min_store_count"),
        ("memory_count", "min_memory_count"),
        ("operation_count", "min_operation_count"),
        ("attributed_memory_count", "min_attributed_memories"),
        ("read_operation_count", "min_read_operations"),
        ("write_operation_count", "min_write_operations"),
        ("recall_operation_count", "min_recall_operations"),
        ("observability_hook_count", "min_observability_hooks"),
        ("artifact_count", "min_artifact_count"),
    )
    for summary_key, quality_key in count_checks:
        count = _as_int(lineage_summary.get(summary_key))
        if count <= 0 and summary_key in {
            "store_count",
            "memory_count",
            "operation_count",
        }:
            count = _as_int(framework_summary.get(summary_key))
        if count > 0:
            quality[quality_key] = count
    for operation_type, quality_key in (
        ("read", "min_read_operations"),
        ("write", "min_write_operations"),
        ("recall", "min_recall_operations"),
    ):
        if operation_type in operation_types and quality_key not in quality:
            quality[quality_key] = 1
    for summary_key, quality_key in (
        ("unattributed_memory_count", "max_unattributed_memories"),
        ("poisoned_memory_count", "max_poisoned_memories"),
        ("open_poisoning_count", "max_open_poisoning"),
        ("isolation_violation_count", "max_isolation_violations"),
        ("retention_violation_count", "max_retention_violations"),
        ("policy_violation_count", "max_policy_violations"),
        ("blocking_gap_count", "max_blocking_gaps"),
    ):
        quality[quality_key] = _as_int(lineage_summary.get(summary_key))
    for flag, signal in lineage_checks:
        if lineage_summary.get(flag):
            quality[f"require_{signal}s" if signal == "store" else f"require_{signal}"] = True
    if quality.pop("require_memory_record", None):
        quality["require_memory_records"] = True
    if quality.pop("require_operation", None):
        quality["require_operations"] = True
    if quality.pop("require_canary", None):
        quality["require_canaries"] = True
    if quality.pop("require_artifact", None):
        quality["require_artifacts"] = True
    if policy_keys:
        quality["required_policies"] = policy_keys
    if operation_types:
        quality["required_operation_types"] = operation_types
    required_evidence = [
        signal
        for _, signal in lineage_checks
        if signal not in {"target"} and lineage_summary.get(_framework_memory_flag(signal))
    ]
    if required_evidence:
        quality["required_evidence"] = _unique_strings(required_evidence)
    required_signals = _unique_strings(
        [
            "agent_memory_lineage",
            "memory_lineage",
            "memory",
            "provenance",
            *required_evidence,
        ]
    )
    if required_signals:
        quality["required_signals"] = required_signals

    required_retrieval = ["retrieval_memory", "trace"]
    if _as_int(retrieval_summary.get("query_count")) > 0:
        required_retrieval.append("query")
    if _as_int(retrieval_summary.get("document_count")) > 0:
        required_retrieval.append("document")
    if (
        _as_int(retrieval_summary.get("citation_count")) > 0
        or _plain_list(retrieval_summary.get("citation_doc_ids"))
    ):
        required_retrieval.extend(["citation", "attribution"])
    if (
        bool(retrieval_summary.get("require_current"))
        or _as_int(retrieval_summary.get("current_document_count")) > 0
    ):
        required_retrieval.append("freshness")
    if _as_int(retrieval_summary.get("memory_write_count")) > 0:
        required_retrieval.append("memory_write")

    return {
        "required_agent_memory_lineage": _unique_strings(required_lineage),
        "agent_memory_lineage_quality": quality,
        "required_retrieval_memory_trace": _unique_strings(required_retrieval),
    }


def _framework_memory_flag(signal: str) -> str:
    flags = {
        "store": "has_stores",
        "memory_record": "has_memory_records",
        "operation": "has_operations",
        "lineage": "has_lineage",
        "source_attribution": "has_source_attribution",
        "tenant_isolation": "has_tenant_isolation",
        "audit": "has_audit",
        "retention_policy": "has_retention_policy",
        "deletion_policy": "has_deletion_policy",
        "redaction": "has_redaction",
        "canary": "has_canaries",
        "observability": "has_observability",
        "artifact": "has_artifacts",
    }
    return flags.get(signal, signal)


def _framework_probe_browser_cua_requirements(
    framework: str,
    summary: Mapping[str, Any],
) -> dict[str, Any]:
    summary = _plain_mapping(summary)
    required_trace = ["trace"]
    if _as_int(summary.get("snapshot_count")) > 0:
        required_trace.append("snapshot")
    if _as_int(summary.get("dom_snapshot_count")) > 0:
        required_trace.append("dom")
    if _as_int(summary.get("screenshot_count")) > 0 or _as_int(summary.get("screenshot_snapshot_count")) > 0:
        required_trace.append("screenshot")
    if _as_int(summary.get("action_count")) > 0:
        required_trace.extend(["action", "action_replay"])
    if _as_int(summary.get("region_count")) > 0:
        required_trace.append("coordinate_region")
    if _as_int(summary.get("screenshot_diff_count")) > 0:
        required_trace.append("screenshot_diff")
    if _as_int(summary.get("network_request_count")) > 0:
        required_trace.append("network")
    if bool(summary.get("storage_present")):
        required_trace.append("storage_state")
    if _as_int(summary.get("runtime_event_count")) > 0:
        required_trace.append("runtime_event")
    if _as_int(summary.get("performance_entry_count")) > 0:
        required_trace.append("performance_entry")
    if _as_int(summary.get("prompt_injection_surface_count")) > 0:
        required_trace.append("prompt_injection_surface")
    if bool(summary.get("layout_shift_present")):
        required_trace.extend(["layout_shift", "layout_shift_distribution"])
    if _as_int(summary.get("mutation_count")) > 0:
        required_trace.extend(["browser_mutation", "browser_mutation_pack"])
    required_trace.extend(_plain_list(summary.get("mutation_types")))

    actions = [_plain_mapping(item) for item in _plain_list(summary.get("actions"))]
    expected_actions: list[dict[str, Any]] = []
    expected_regions: list[dict[str, Any]] = []
    for action in actions:
        spec: dict[str, Any] = {}
        tool = str(action.get("tool") or action.get("tool_name") or "")
        if tool:
            spec["tool"] = tool
        for key in ("action", "selector", "success", "matched", "blocked"):
            if action.get(key) not in (None, "", [], {}):
                spec[key] = action[key]
        if action.get("mutation_id"):
            spec["mutation_id"] = str(action["mutation_id"])
        if action.get("mutation_type"):
            spec["mutation_type"] = str(action["mutation_type"])
        if spec:
            expected_actions.append(spec)

        region = _plain_mapping(action.get("region"))
        region_spec: dict[str, Any] = {}
        if region.get("id") or region.get("name"):
            region_spec["name"] = str(region.get("id") or region.get("name"))
        if region.get("selector") or action.get("selector"):
            region_spec["selector"] = str(region.get("selector") or action.get("selector"))
        if action.get("success") is not None:
            region_spec["success"] = bool(action.get("success"))
        if region_spec:
            expected_regions.append(region_spec)

    runtime_events = [
        _plain_mapping(item)
        for item in _plain_list(summary.get("runtime_events"))
        if _plain_mapping(item)
    ]
    expected_runtime_events: list[dict[str, Any]] = []
    for event in runtime_events:
        spec: dict[str, Any] = {}
        if event.get("type"):
            spec["type"] = str(event["type"])
        if event.get("level"):
            spec["level"] = str(event["level"])
        if event.get("message"):
            spec["message_contains"] = str(event["message"])
        if spec:
            expected_runtime_events.append(spec)

    mutation_ids = _unique_strings(summary.get("mutation_ids"))
    mutation_types = _unique_strings(summary.get("mutation_types"))
    tool_names = _unique_strings(summary.get("tool_names"))
    mitigations: list[str] = []
    if _as_int(summary.get("mutation_count")) > 0:
        mitigations.append("browser_mutations")
    if bool(summary.get("storage_present")):
        mitigations.append("storage_recheck")
    if _as_int(summary.get("runtime_event_count")) > 0 or _as_int(summary.get("performance_entry_count")) > 0:
        mitigations.append("runtime_recheck")
    mitigations.extend(tool_names)
    if any(action.get("mutation_id") for action in actions):
        mitigations.append("mutation_action")
    if any(action.get("mutation_id") and action.get("success") is True for action in actions):
        mitigations.append("mutation_action_success")

    config: dict[str, Any] = {
        "required_browser_trace": _unique_strings(required_trace),
        "expected_browser_actions": expected_actions[:5],
        "expected_browser_regions": expected_regions[:5],
        "expected_browser_runtime_events": expected_runtime_events[:5],
        "forbidden_browser_runtime_events": [{"level": "error"}],
        "allow_stale_browser_screenshot": _as_int(summary.get("stale_action_count")) > 0,
    }
    if _as_int(summary.get("screenshot_diff_count")) > 0:
        config["expected_browser_screenshot_diffs"] = [{}]
    if bool(summary.get("layout_shift_present")):
        config["expected_browser_perturbations"] = [
            {"id": "layout_shift_distribution", "type": "layout_shift"}
        ]
    max_layout_shift = _as_float(summary.get("max_layout_shift_score"))
    if max_layout_shift > 0:
        config["max_browser_layout_shift_score"] = max_layout_shift
    max_performance = _as_float(summary.get("max_performance_duration_ms"))
    if max_performance > 0:
        config["max_browser_performance_duration_ms"] = max_performance
    prompt_ids = _unique_strings(summary.get("prompt_injection_ids"))
    if prompt_ids:
        config["forbidden_browser_prompt_injection_targets"] = [
            {"id": prompt_id} for prompt_id in prompt_ids[:5]
        ]
    if mutation_ids:
        config["required_browser_mutations"] = mutation_ids
    mutation_resilience: dict[str, Any] = {
        "framework": framework,
        "required_types": mutation_types,
        "required_mitigations": _unique_strings(mitigations),
        "expected_actions": [
            action
            for action in expected_actions[:5]
            if action.get("mutation_id") or action.get("mutation_type")
        ],
        "forbidden_runtime_events": [{"level": "error"}],
        "max_runtime_errors": 0,
    }
    config["browser_mutation_resilience"] = {
        key: value
        for key, value in mutation_resilience.items()
        if value not in (None, "", [], {})
    }
    return config


def _framework_probe_trace_requirements(
    framework: str,
    summary: Mapping[str, Any],
) -> list[str]:
    summary = _plain_mapping(summary)
    requirements = ["framework_trace"]
    requirements.extend(_plain_list(summary.get("signals")))
    signal_checks = (
        ("model_span_count", "model"),
        ("tool_span_count", "tool"),
        ("retrieval_span_count", "retrieval"),
        ("memory_span_count", "memory"),
        ("state_span_count", "state"),
        ("latency_span_count", "latency"),
        ("cost_span_count", "cost"),
        ("error_count", "error"),
        ("checkpoint_count", "checkpoint"),
        ("session_count", "session"),
    )
    for summary_key, signal in signal_checks:
        if _as_int(summary.get(summary_key)) > 0:
            requirements.append(signal)
    if _as_int(summary.get("span_count")) > 0 or _as_int(summary.get("event_count")) > 0:
        requirements.append("span")
    if _plain_list(summary.get("tool_names")):
        requirements.append("tool")
    if framework:
        requirements.append("framework")
    return _unique_strings(str(item) for item in requirements if str(item))


def _framework_probe_trace_quality_requirements(
    framework: str,
    summary: Mapping[str, Any],
) -> dict[str, Any]:
    summary = _plain_mapping(summary)
    quality: dict[str, Any] = {"framework": framework}
    for summary_key, quality_key in (
        ("span_count", "min_span_count"),
        ("event_count", "min_event_count"),
        ("signal_count", "min_signal_count"),
        ("model_span_count", "min_model_span_count"),
        ("tool_span_count", "min_tool_span_count"),
        ("retrieval_span_count", "min_retrieval_span_count"),
        ("memory_span_count", "min_memory_span_count"),
        ("state_span_count", "min_state_span_count"),
        ("latency_span_count", "min_latency_span_count"),
        ("cost_span_count", "min_cost_span_count"),
        ("checkpoint_count", "min_checkpoint_count"),
        ("session_count", "min_session_count"),
        ("tool_count", "min_tool_count"),
    ):
        count = _as_int(summary.get(summary_key))
        if count > 0:
            quality[quality_key] = count
    signals = _unique_strings(summary.get("signals"))
    if signals:
        quality["required_signals"] = signals
    tool_names = _unique_strings(summary.get("tool_names"))
    if tool_names:
        quality["required_tools"] = tool_names
    span_names = _unique_strings(summary.get("span_names"))
    if span_names:
        quality["required_spans"] = span_names[:10]
    event_names = _unique_strings(summary.get("event_names"))
    if event_names:
        quality["required_events"] = event_names[:10]
    if summary.get("adapter_conformance_passed") is True:
        quality["require_adapter_conformance"] = True
    finding_count = _as_int(summary.get("adapter_conformance_finding_count"))
    if finding_count >= 0:
        quality["max_adapter_conformance_findings"] = finding_count
    error_count = _as_int(summary.get("error_count"))
    if error_count >= 0:
        quality["max_error_count"] = error_count
    return {
        key: value
        for key, value in quality.items()
        if value not in (None, "", [], {})
    }


def _framework_probe_transcript_quality_requirements(
    framework: str,
    message_summary: Mapping[str, Any],
    handoff_summary: Mapping[str, Any],
) -> dict[str, Any]:
    del framework
    message_summary = _plain_mapping(message_summary)
    handoff_summary = _plain_mapping(handoff_summary)
    quality: dict[str, Any] = {}

    message_count = _as_int(message_summary.get("message_count"))
    if message_count > 0:
        quality["min_turns"] = message_count

    message_types = _unique_strings(message_summary.get("message_types") or message_summary.get("types"))
    event_methods = [
        *message_types,
        *(["handoff"] if _as_int(handoff_summary.get("handoff_count")) > 0 else []),
        *(["review"] if _as_int(handoff_summary.get("review_count")) > 0 else []),
        *(["reconciliation"] if _as_int(handoff_summary.get("reconciliation_count")) > 0 else []),
    ]
    if message_summary.get("stop_reason"):
        event_methods.append("termination")
    if event_methods:
        quality["required_event_methods"] = _unique_strings(event_methods)

    speaker_sequence = [
        str(item).strip()
        for item in _plain_list(message_summary.get("speaker_sequence"))
        if str(item or "").strip()
    ]
    required_speakers = _unique_strings(
        [
            *speaker_sequence,
            *_plain_list(message_summary.get("sources")),
            *_plain_list(handoff_summary.get("participants")),
        ]
    )
    if required_speakers:
        quality["required_speakers"] = required_speakers
    if len(speaker_sequence) > 1:
        quality["expected_speaker_sequence"] = speaker_sequence[:20]

    tool_names = _unique_strings(message_summary.get("tool_names"))
    if tool_names:
        quality["expected_tool_sequence"] = tool_names

    handoff_sources = _plain_list(handoff_summary.get("handoffs")) or _plain_list(
        message_summary.get("handoffs")
    )
    expected_handoffs = _framework_probe_expected_handoffs(handoff_sources)
    if expected_handoffs:
        quality["expected_handoffs"] = expected_handoffs

    stop_reason = str(message_summary.get("stop_reason") or "").strip()
    if stop_reason:
        quality["require_termination"] = True
        quality["termination_contains"] = [stop_reason]

    last_content = str(message_summary.get("last_content") or "").strip()
    output_fragment = _framework_probe_output_fragment(last_content)
    if output_fragment:
        quality["output_contains"] = [output_fragment]

    expected_state: dict[str, Any] = {}
    if message_count > 0:
        expected_state["message_history"] = {"message_count": message_count}
    for summary_key, state_key in (
        ("handoff_count", "handoff_count"),
        ("review_count", "review_count"),
        ("reconciliation_count", "reconciliation_count"),
    ):
        count = _as_int(handoff_summary.get(summary_key))
        if count > 0:
            expected_state.setdefault("framework_handoffs", {})[state_key] = count
    if expected_state:
        quality["expected_state"] = expected_state

    return {
        key: value
        for key, value in quality.items()
        if value not in (None, "", [], {})
    }


def _framework_probe_expected_handoffs(value: Sequence[Any]) -> list[dict[str, Any]]:
    handoffs: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for raw_handoff in value:
        handoff = _plain_mapping(raw_handoff)
        if not handoff:
            continue
        source = str(
            handoff.get("from")
            or handoff.get("source")
            or handoff.get("handoff_from")
            or ""
        ).strip()
        target = str(
            handoff.get("to")
            or handoff.get("target")
            or handoff.get("handoff_to")
            or ""
        ).strip()
        task = str(handoff.get("task") or handoff.get("description") or "").strip()
        key = (source, target, task)
        if key in seen:
            continue
        seen.add(key)
        spec: dict[str, Any] = {}
        if source:
            spec["from"] = source
        if target:
            spec["to"] = target
        if task:
            spec["task_contains"] = [_framework_probe_output_fragment(task) or task]
        if spec:
            handoffs.append(spec)
    return handoffs


def _framework_probe_output_fragment(value: str) -> str:
    text = " ".join(str(value or "").split())
    if not text:
        return ""
    if len(text) <= 160:
        return text
    return text[:160].rstrip()


def _framework_probe_orchestration_requirements(
    framework: str,
    summary: Mapping[str, Any],
) -> dict[str, Any]:
    summary = _plain_mapping(summary)
    required_trace = ["orchestration_trace", "trace", "step"]
    required_trace.extend(_plain_list(summary.get("signals")))
    signal_checks = (
        ("node_count", "node"),
        ("edge_count", "route"),
        ("agent_count", "agent"),
        ("spawn_count", "spawn"),
        ("delegation_count", "delegate"),
        ("communication_count", "communicate"),
        ("aggregation_count", "aggregate"),
        ("stop_count", "stop"),
        ("retry_count", "retry"),
        ("recovered_failures", "recovered"),
        ("failure_count", "error"),
        ("total_latency_ms", "latency"),
        ("total_cost", "cost"),
    )
    for summary_key, signal in signal_checks:
        value = summary.get(summary_key)
        if summary_key in {"total_latency_ms", "total_cost"}:
            observed = value not in (None, "", [], {})
        else:
            observed = _as_int(value) > 0
        if observed:
            required_trace.append(signal)
    if "state" in set(_plain_list(summary.get("signals"))):
        required_trace.append("state")
    if "tool" in set(_plain_list(summary.get("signals"))):
        required_trace.append("tool")
    if framework:
        required_trace.append("framework")

    quality: dict[str, Any] = {"framework": framework}
    node_names = _unique_strings(summary.get("node_names"))
    if node_names:
        quality["required_nodes"] = node_names
    for summary_key, quality_key in (
        ("agent_count", "min_agent_count"),
        ("spawn_count", "min_spawn_count"),
        ("delegation_count", "min_delegation_count"),
        ("communication_count", "min_communication_count"),
        ("aggregation_count", "min_aggregation_count"),
        ("stop_count", "min_stop_count"),
        ("retry_count", "min_retry_count"),
    ):
        count = _as_int(summary.get(summary_key))
        if count > 0:
            quality[quality_key] = count
    if _as_int(summary.get("aggregation_count")) > 0:
        quality["require_aggregation"] = True
    if _as_int(summary.get("stop_count")) > 0:
        quality["require_stop_decision"] = True
    if _as_int(summary.get("recovered_failures")) > 0:
        quality["require_recovered_errors"] = True
    failure_count = _as_int(summary.get("failure_count"))
    if failure_count >= 0:
        quality["max_error_count"] = failure_count
    terminal_status = str(summary.get("terminal_status") or "")
    if terminal_status:
        quality["terminal_status"] = terminal_status
    return {
        "required_orchestration_trace": _unique_strings(
            str(item) for item in required_trace if str(item)
        ),
        "orchestration_trace_quality": quality,
    }


def _framework_probe_workflow_requirements(
    framework: str,
    summary: Mapping[str, Any],
) -> dict[str, Any]:
    summary = _plain_mapping(summary)
    required_trace = ["workflow_trace", "trace"]
    count_signals = (
        ("node_count", "node"),
        ("edge_count", "edge"),
        ("step_count", "step"),
        ("checkpoint_count", "checkpoint"),
        ("route_decision_count", "route"),
        ("interrupt_count", "interrupt"),
        ("replay_count", "replay"),
        ("write_count", "write"),
        ("state_snapshot_count", "state_snapshot"),
        ("tool_call_count", "tool_call"),
    )
    for summary_key, signal in count_signals:
        if _as_int(summary.get(summary_key)) > 0:
            required_trace.append(signal)
            if signal in {"node", "edge"}:
                required_trace.append("graph")
            if signal in {"checkpoint", "write", "state_snapshot"}:
                required_trace.append("state")
            if signal == "tool_call":
                required_trace.append("tool")
    if _plain_list(summary.get("final_state_keys")):
        required_trace.extend(["final_state", "state"])
    if bool(summary.get("has_topology")) or _plain_list(summary.get("entry_nodes")) or _plain_list(summary.get("terminal_nodes")):
        required_trace.append("topology")
    if framework:
        required_trace.append("framework")

    quality: dict[str, Any] = {"framework": framework}
    for summary_key, quality_key in (
        ("node_count", "min_node_count"),
        ("edge_count", "min_edge_count"),
        ("step_count", "min_step_count"),
        ("checkpoint_count", "min_checkpoint_count"),
        ("route_decision_count", "min_route_decision_count"),
        ("interrupt_count", "min_interrupt_count"),
        ("replay_count", "min_replay_count"),
        ("write_count", "min_write_count"),
        ("state_snapshot_count", "min_state_snapshot_count"),
        ("tool_call_count", "min_tool_call_count"),
    ):
        count = _as_int(summary.get(summary_key))
        if count > 0:
            quality[quality_key] = count
    for summary_key, quality_key in (
        ("node_names", "required_nodes"),
        ("step_names", "required_steps"),
        ("tool_names", "required_tools"),
        ("step_statuses", "required_step_statuses"),
        ("final_state_keys", "required_final_state_keys"),
        ("entry_nodes", "required_entry_nodes"),
        ("terminal_nodes", "required_terminal_nodes"),
    ):
        values = _unique_strings(summary.get(summary_key))
        if values:
            quality[quality_key] = values
    if bool(summary.get("has_replay")) or _as_int(summary.get("replay_count")) > 0:
        quality["require_replay"] = True
    if bool(summary.get("has_interrupts")) or _as_int(summary.get("interrupt_count")) > 0:
        quality["require_interrupts"] = True
    if bool(summary.get("has_routes")) or _as_int(summary.get("route_decision_count")) > 0:
        quality["require_routes"] = True
    if bool(summary.get("has_topology")) or _plain_list(summary.get("entry_nodes")) or _plain_list(summary.get("terminal_nodes")):
        quality["require_topology"] = True
    error_count = _as_int(summary.get("error_count"))
    if error_count >= 0:
        quality["max_error_count"] = error_count

    return {
        "required_workflow_trace": _unique_strings(
            str(item) for item in required_trace if str(item)
        ),
        "workflow_trace_quality": {
            key: value
            for key, value in quality.items()
            if value not in (None, "", [], {})
        },
    }


def _framework_probe_openenv_requirements(
    framework: str,
    summary: Mapping[str, Any],
) -> dict[str, Any]:
    summary = _plain_mapping(summary)
    required = ["openenv", "state", "observation"]
    signal_checks = (
        ("reset_count", "reset"),
        ("step_count", "step"),
        ("action_route_count", "action"),
        ("step_count", "reward"),
        ("metadata_capture_count", "metadata"),
        ("failure_count", "failure_injection"),
    )
    for summary_key, signal in signal_checks:
        if _as_int(summary.get(summary_key)) > 0:
            required.append(signal)
    if bool(summary.get("done")):
        required.append("done")
    if bool(summary.get("terminated")):
        required.append("terminated")
    if bool(summary.get("truncated")):
        required.append("truncated")
    if bool(summary.get("sandbox_enabled")):
        required.append("sandbox")
    for key in ("runtime", "transport"):
        if summary.get(key) not in (None, "", [], {}):
            required.append(str(summary[key]))
    required.extend(_plain_list(summary.get("signals")))

    quality: dict[str, Any] = {"framework": framework}
    for summary_key, quality_key in (
        ("reset_count", "min_reset_count"),
        ("step_count", "min_step_count"),
        ("action_route_count", "min_action_route_count"),
        ("failure_count", "min_failure_count"),
        ("metadata_capture_count", "min_metadata_capture_count"),
    ):
        count = _as_int(summary.get(summary_key))
        if count > 0:
            quality[quality_key] = count
    reward_total = _as_float(summary.get("reward_total"))
    if reward_total > 0:
        quality["min_reward_total"] = reward_total
    error_count = _as_int(summary.get("error_count"))
    if error_count >= 0:
        quality["max_error_count"] = error_count
    if bool(summary.get("done")):
        quality["require_done"] = True
    if bool(summary.get("terminated")):
        quality["require_terminated"] = True
    if bool(summary.get("truncated")):
        quality["require_truncated"] = True
    if bool(summary.get("sandbox_enabled")):
        quality["require_sandbox"] = True
    if _as_int(summary.get("metadata_capture_count")) > 0:
        quality["require_metadata_capture"] = True
    if summary.get("requires_external_service") is not None:
        quality["require_no_external_service"] = not bool(
            summary.get("requires_external_service")
        )
    if summary.get("deterministic_reset") is not None:
        quality["require_deterministic_reset"] = bool(
            summary.get("deterministic_reset")
        )
    for summary_key, quality_key in (
        ("runtime", "required_runtime"),
        ("transport", "required_transport"),
        ("isolation", "required_isolation"),
    ):
        if summary.get(summary_key) not in (None, "", [], {}):
            quality[quality_key] = str(summary[summary_key])
    return {
        "required_openenv": _unique_strings(str(item) for item in required if str(item)),
        "openenv_quality": {
            key: value
            for key, value in quality.items()
            if value not in (None, "", [], {})
        },
    }


