def _long_horizon_canary_terms(values: Any) -> list[str]:
    terms: list[str] = []
    for item in values or []:
        if isinstance(item, Mapping):
            value = item.get("value") or item.get("secret") or item.get("canary")
        else:
            value = item
        text = str(value or "")
        if text:
            terms.append(text)
    return _unique_strings(terms)


