def _external_agent_adapter_candidates(
    *,
    endpoint: Optional[str],
    base_url: Optional[str],
    model: str,
    api_key_env: str,
) -> list[dict[str, Any]]:
    def candidate(
        *,
        agent_type: str,
        protocol: str,
        include_tools: bool,
        profile: str,
    ) -> dict[str, Any]:
        agent: dict[str, Any] = {
            "type": agent_type,
            "protocol": protocol,
            "model": str(model),
            "api_key_env": str(api_key_env),
            "include_tools": bool(include_tools),
            "timeout": 5.0,
            "metadata": {"candidate_profile": profile},
        }
        if endpoint:
            agent["endpoint"] = str(endpoint)
        if base_url:
            agent["base_url"] = str(base_url)
        return agent

    return [
        candidate(
            agent_type="http",
            protocol="fi.alk",
            include_tools=True,
            profile="raw_http_agent_learning_payload",
        ),
        candidate(
            agent_type="openai_compatible",
            protocol="openai_chat",
            include_tools=False,
            profile="openai_compatible_without_tool_schema",
        ),
        candidate(
            agent_type="openai_compatible",
            protocol="openai_chat",
            include_tools=True,
            profile="verified_openai_compatible_tools",
        ),
    ]


def _workflow_hook_environment_candidates(
    *,
    endpoint: str,
    tool_name: str,
    api_key_env: str,
) -> list[list[dict[str, Any]]]:
    def workflow_candidate(
        *,
        include_auth: bool,
        profile: str,
    ) -> list[dict[str, Any]]:
        hook: dict[str, Any] = {
            "endpoint": str(endpoint),
            "method": "POST",
            "description": "Execute the refund workflow hook.",
            "schema": {
                "description": "Execute the refund workflow hook.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "customer_id": {"type": "string"},
                        "amount": {"type": "number"},
                        "currency": {"type": "string"},
                        "action": {"type": "string"},
                    },
                    "required": ["customer_id", "amount", "action"],
                },
            },
            "metadata": {"candidate_profile": profile},
        }
        if include_auth and api_key_env:
            hook["auth"] = {"type": "bearer", "token_env": str(api_key_env)}
        return [
            {
                "type": "workflow_hook",
                "data": {
                    "hooks": {str(tool_name): hook},
                    "metadata": {"candidate_profile": profile},
                },
            }
        ]

    return [
        [
            {
                "type": "tool_mock",
                "data": {
                    "tools": {
                        str(tool_name): {
                            "schema": {
                                "description": "Mock refund workflow hook.",
                                "parameters": {
                                    "type": "object",
                                    "properties": {
                                        "customer_id": {"type": "string"},
                                        "amount": {"type": "number"},
                                        "action": {"type": "string"},
                                    },
                                },
                            },
                            "response": {
                                "content": (
                                    "Workflow hook not executed; refund "
                                    "approval remains pending and auth "
                                    "redaction is unverified."
                                ),
                                "result": {"status": "pending", "mocked": True},
                                "success": False,
                                "state_updates": {
                                    "refund_workflow": {
                                        "status": "pending",
                                        "mocked": True,
                                    }
                                },
                            },
                        }
                    },
                    "metadata": {
                        "candidate_profile": "mocked_without_http_execution"
                    },
                },
            }
        ],
        workflow_candidate(
            include_auth=False,
            profile="http_workflow_hook_missing_auth",
        ),
        workflow_candidate(
            include_auth=True,
            profile="verified_authenticated_workflow_hook",
        ),
    ]


