def _artifact_action_candidate_job(
    *,
    name: str,
    artifact_path: str,
    action: Mapping[str, Any],
    inputs: Mapping[str, Any],
    cwd_root: str,
    outputs_root: str,
) -> dict[str, Any]:
    action_id = str(action.get("id") or "")
    safe_action = _safe_slug(action_id)
    job: dict[str, Any] = {
        "id": f"artifact-action-{safe_action}",
        "command": "action-run",
        "path": artifact_path,
        "action_id": action_id,
        "action_kind": str(action.get("kind") or "cli"),
        "name": f"{name}-{safe_action}",
        "cwd": _join_path_text(cwd_root, safe_action),
        "output": _join_path_text(outputs_root, safe_action, "action-run.json"),
        "outputs": {
            "markdown": _join_path_text(outputs_root, safe_action, "action-run.md")
        },
    }
    if str(action.get("kind") or "cli") == "download":
        job["artifact_output"] = str(
            action.get("default_filename") or f"{safe_action}.json"
        )
    if inputs:
        job["inputs"] = copy.deepcopy(dict(inputs))
    return job


def _artifact_action_is_executable(
    action: Mapping[str, Any],
    *,
    inputs: Mapping[str, Any],
    include_requires_input: bool,
) -> bool:
    action_kind = str(action.get("kind") or "cli")
    if action_kind == "download":
        return bool(action.get("artifact_ref"))
    if action_kind != "cli":
        return False

    command_args = action.get("command_args")
    if not isinstance(command_args, Sequence) or isinstance(command_args, (str, bytes)):
        return False
    if len(command_args) < 2:
        return False
    command_name = str(command_args[0])
    if command_name != "agent-learn":
        return False
    subcommand = str(command_args[1]).strip().lower().replace("_", "-")
    if subcommand in {"action-run", "run-action"}:
        return False
    if bool(action.get("requires_input") or action.get("inputs")):
        if not include_requires_input and not inputs:
            return False
    try:
        _resolved_artifact_action_args(action, inputs)
    except ValueError:
        return False
    return True


def _artifact_action_matches_scope(
    action: Mapping[str, Any],
    *,
    source_card_paths: set[str],
    target_layers: set[str],
    command_subcommands: set[str],
) -> bool:
    if source_card_paths and str(action.get("source_card_path") or "") not in source_card_paths:
        return False
    if target_layers:
        observed_layers = {_scope_key(item) for item in action.get("target_layers") or []}
        observed_layers.update(
            _scope_key(value)
            for value in (
                action.get("readiness_layer"),
                action.get("strategy_layer"),
                action.get("diagnosis_layer"),
            )
            if value
        )
        if not observed_layers.intersection(target_layers):
            return False
    if command_subcommands:
        if str(action.get("kind") or "cli") != "cli":
            return False
        args = list(action.get("command_args") or [])
        subcommand = _scope_key(args[1]) if len(args) > 1 else ""
        if subcommand not in command_subcommands:
            return False
    return True


def _artifact_action_scope_filters(
    *,
    action_ids: Sequence[str],
    exclude_action_ids: set[str],
    source_card_paths: set[str],
    target_layers: set[str],
    command_subcommands: set[str],
    include_synthesized_report_actions: bool,
    include_requires_input: bool,
) -> dict[str, Any]:
    return {
        "action_ids": [str(item) for item in action_ids],
        "exclude_action_ids": sorted(exclude_action_ids),
        "source_card_paths": sorted(source_card_paths),
        "target_layers": sorted(target_layers),
        "command_subcommands": sorted(command_subcommands),
        "include_synthesized_report_actions": bool(include_synthesized_report_actions),
        "include_requires_input": bool(include_requires_input),
    }


def _scope_key(value: Any) -> str:
    return str(value or "").strip().lower().replace("-", "_").replace(" ", "_")


def _plain_mapping(value: Any) -> dict[str, Any]:
    return dict(value) if isinstance(value, Mapping) else {}


def _plain_list(value: Any) -> list[Any]:
    if value is None:
        return []
    if isinstance(value, list):
        return value
    return [value]


def _as_int(value: Any) -> int:
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    if isinstance(value, str):
        try:
            return int(float(value.strip()))
        except ValueError:
            return 0
    return 0


def _as_float(value: Any) -> float:
    if isinstance(value, bool):
        return float(value)
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except ValueError:
            return 0.0
    return 0.0


def _world_hook_environment(
    environments: Sequence[Mapping[str, Any]],
    environment_type: str,
) -> dict[str, Any]:
    for environment in environments:
        if _scope_key(environment.get("type")) == _scope_key(environment_type):
            return copy.deepcopy(dict(environment))
    return {}


def _selected_optimization_history(
    payload: Mapping[str, Any],
    optimization: Mapping[str, Any],
) -> dict[str, Any]:
    history = [
        _plain_mapping(item)
        for item in _plain_list(optimization.get("history"))
        if _plain_mapping(item)
    ]
    selected_candidate_id = str(
        optimization.get("best_candidate_id")
        or _plain_mapping(payload.get("summary")).get("best_candidate_id")
        or ""
    )
    if selected_candidate_id:
        for row in history:
            if str(row.get("candidate_id") or "") == selected_candidate_id:
                return row
    if history:
        return max(history, key=lambda row: _as_float(row.get("score")))
    return {}


def _world_hook_selected_history(
    payload: Mapping[str, Any],
    optimization: Mapping[str, Any],
) -> dict[str, Any]:
    return _selected_optimization_history(payload, optimization)


def _selected_report_environment_state(
    selected_history: Mapping[str, Any],
) -> dict[str, Any]:
    report = _plain_mapping(selected_history.get("report"))
    result_rows = [
        _plain_mapping(item)
        for item in _plain_list(report.get("results"))
        if _plain_mapping(item)
    ]
    if not result_rows:
        return {}
    metadata = _plain_mapping(result_rows[0].get("metadata"))
    return _plain_mapping(metadata.get("environment_state"))


def _world_hook_report_environment_state(
    selected_history: Mapping[str, Any],
) -> dict[str, Any]:
    return _selected_report_environment_state(selected_history)


def _is_framework_runtime_optimization(
    payload: Mapping[str, Any],
    optimization: Mapping[str, Any],
) -> bool:
    if _is_framework_certification_optimization(payload, optimization):
        return False

    source_manifest = _plain_mapping(optimization.get("source_manifest"))
    source_metadata = _plain_mapping(source_manifest.get("metadata"))
    source_optimization = _plain_mapping(source_manifest.get("optimization"))
    target = _plain_mapping(_plain_mapping(source_optimization.get("target")))
    metadata = {
        **source_metadata,
        **_plain_mapping(target.get("metadata")),
    }
    if _scope_key(metadata.get("task_kind")) in {
        "framework_adapter",
        "social_memory_framework",
    }:
        return True

    best_config = _plain_mapping(optimization.get("best_config"))
    best_agent = _plain_mapping(best_config.get("agent"))
    if _scope_key(best_agent.get("type")) == "framework":
        return True

    selected_history = _selected_optimization_history(payload, optimization)
    state_keys = set(_selected_report_environment_state(selected_history))
    return {"framework_runtime", "framework_trace"}.issubset(state_keys)


def _is_framework_certification_optimization(
    payload: Mapping[str, Any],
    optimization: Mapping[str, Any],
) -> bool:
    source_manifest = _plain_mapping(optimization.get("source_manifest"))
    source_metadata = _plain_mapping(source_manifest.get("metadata"))
    source_optimization = _plain_mapping(source_manifest.get("optimization"))
    target = _plain_mapping(_plain_mapping(source_optimization.get("target")))
    metadata = {
        **source_metadata,
        **_plain_mapping(target.get("metadata")),
    }
    task_kind = _scope_key(metadata.get("task_kind"))
    if task_kind == "framework_certification":
        return True

    best_config = _plain_mapping(optimization.get("best_config"))
    simulation = _plain_mapping(best_config.get("simulation"))
    environment_types = {
        _scope_key(_plain_mapping(item).get("type"))
        for item in _plain_list(simulation.get("environments"))
        if _plain_mapping(item)
    }
    required_environment_types = {
        "framework_lifecycle",
        "framework_capability",
        "framework_probe",
        "framework_portability",
    }
    if required_environment_types.issubset(environment_types):
        return True

    selected_history = _selected_optimization_history(payload, optimization)
    state_keys = set(_selected_report_environment_state(selected_history))
    return {
        "framework_lifecycle_trace",
        "framework_capability_matrix",
        "framework_probe_suite",
        "framework_portability_matrix",
    }.issubset(state_keys)


def _source_manifest_with_optimization(
    optimization: Mapping[str, Any],
) -> dict[str, Any]:
    source_manifest = _plain_mapping(optimization.get("source_manifest"))
    if _plain_mapping(source_manifest.get("optimization")):
        return source_manifest

    source_manifest_path = str(optimization.get("source_manifest_path") or "")
    if not source_manifest_path:
        return source_manifest

    try:
        loaded = json.loads(
            Path(source_manifest_path).expanduser().read_text(encoding="utf-8")
        )
    except (OSError, TypeError, ValueError):
        return source_manifest

    loaded_manifest = _plain_mapping(loaded)
    if not loaded_manifest:
        return source_manifest
    return {**source_manifest, **loaded_manifest}


def _is_workspace_import_certification_optimization(
    payload: Mapping[str, Any],
    optimization: Mapping[str, Any],
) -> bool:
    del payload

    source_manifest = _source_manifest_with_optimization(optimization)
    source_metadata = _plain_mapping(source_manifest.get("metadata"))
    source_optimization = _plain_mapping(
        source_manifest.get("optimization")
    ) or _plain_mapping(optimization.get("manifest_optimization"))
    target = _plain_mapping(_plain_mapping(source_optimization.get("target")))
    metadata = {
        **source_metadata,
        **_plain_mapping(target.get("metadata")),
    }
    if _scope_key(metadata.get("task_kind")) == "workspace_import_certification":
        return True

    if _scope_key(metadata.get("cookbook")) in {
        "workspace_import_certification",
        "workspace_import_certification_optimization",
        "sdk_workspace_import_certification",
    }:
        return True

    return (
        "build_workspace_import_certification_optimization_manifest"
        in _scope_key(metadata.get("source"))
    )


