def _is_memory_lineage_optimization(
    payload: Mapping[str, Any],
    optimization: Mapping[str, Any],
) -> bool:
    source_manifest = _plain_mapping(optimization.get("source_manifest"))
    source_metadata = _plain_mapping(source_manifest.get("metadata"))
    source_optimization = _plain_mapping(source_manifest.get("optimization"))
    target = _plain_mapping(_plain_mapping(source_optimization.get("target")))
    metadata = {
        **source_metadata,
        **_plain_mapping(target.get("metadata")),
    }
    task_kind = _scope_key(metadata.get("task_kind"))
    if task_kind in {"memory_retrieval", "memory_layer"}:
        return True

    best_config = _plain_mapping(optimization.get("best_config"))
    simulation = _plain_mapping(best_config.get("simulation"))
    environment_types = [
        _scope_key(_plain_mapping(item).get("type"))
        for item in _plain_list(simulation.get("environments"))
        if _plain_mapping(item)
    ]
    # Keep this proof scoped to the dedicated memory bundle. Larger orchestration
    # stacks may include the same environments, but those need their own proof.
    if environment_types == ["retrieval_memory", "agent_memory_lineage"]:
        return True

    selected_history = _selected_optimization_history(payload, optimization)
    state_keys = set(_selected_report_environment_state(selected_history))
    return state_keys == {"retrieval_memory", "agent_memory_lineage"}


def _is_multi_agent_coordination_optimization(
    payload: Mapping[str, Any],
    optimization: Mapping[str, Any],
) -> bool:
    source_manifest = _plain_mapping(optimization.get("source_manifest"))
    source_metadata = _plain_mapping(source_manifest.get("metadata"))
    source_optimization = _plain_mapping(
        source_manifest.get("optimization")
    ) or _plain_mapping(optimization.get("manifest_optimization"))
    target = _plain_mapping(_plain_mapping(source_optimization.get("target")))
    metadata = {
        **source_metadata,
        **_plain_mapping(target.get("metadata")),
    }
    task_kind = _scope_key(metadata.get("task_kind"))
    if task_kind in {"multi_agent_coordination", "multi_agent_framework_handoff"}:
        return True
    layers = {_scope_key(layer) for layer in _plain_list(target.get("layers"))}

    best_config = _plain_mapping(optimization.get("best_config"))
    simulation = _plain_mapping(best_config.get("simulation"))
    environment_types = [
        _scope_key(_plain_mapping(item).get("type"))
        for item in _plain_list(simulation.get("environments"))
        if _plain_mapping(item)
    ]
    if environment_types == ["multi_agent_room"]:
        return True
    if (
        {"framework", "multi_agent"}.issubset(layers)
        and "framework_trace" in environment_types
        and "multi_agent_room" in environment_types
    ):
        return True
    if "framework_trace" in environment_types and "multi_agent_room" in environment_types:
        selected_history = _selected_optimization_history(payload, optimization)
        selected_metrics = _plain_mapping(selected_history.get("metrics"))
        if _as_float(selected_metrics.get("multi_agent_coordination_quality")) >= 1.0:
            return True

    selected_history = _selected_optimization_history(payload, optimization)
    return set(_selected_report_environment_state(selected_history)) == {"multi_agent"}


def _is_redteam_campaign_optimization(
    payload: Mapping[str, Any],
    optimization: Mapping[str, Any],
) -> bool:
    source_manifest = _plain_mapping(optimization.get("source_manifest"))
    source_metadata = _plain_mapping(source_manifest.get("metadata"))
    source_optimization = _plain_mapping(source_manifest.get("optimization"))
    target = _plain_mapping(_plain_mapping(source_optimization.get("target")))
    metadata = {
        **source_metadata,
        **_plain_mapping(target.get("metadata")),
    }
    task_kind = _scope_key(metadata.get("task_kind"))
    if task_kind == "redteam_attack_evolution":
        return False
    if task_kind in {
        "redteam_campaign",
        "adaptive_redteam_campaign",
        "long_horizon_redteam_attack_system",
        "redteam_society_council",
        "redteam_causal_attribution_graph",
    }:
        return True

    best_config = _plain_mapping(optimization.get("best_config"))
    simulation = _plain_mapping(best_config.get("simulation"))
    environment_types = {
        _scope_key(_plain_mapping(item).get("type"))
        for item in _plain_list(simulation.get("environments"))
        if _plain_mapping(item)
    }
    if environment_types & {
        "red_team_attack_evolution",
        "redteam_attack_evolution",
        "attack_evolution",
    }:
        return False
    if _plain_mapping(best_config.get("redteam")):
        return True

    selected_history = _selected_optimization_history(payload, optimization)
    report_state = _selected_report_environment_state(selected_history)
    if "red_team_attack_evolution" in report_state:
        return False
    if "red_team_campaign" in report_state and "adversarial" in report_state:
        return True

    redteam_card = _plain_mapping(payload.get("redteam"))
    return bool(redteam_card.get("attack_types") and redteam_card.get("surfaces"))


def _is_redteam_attack_evolution_optimization(
    payload: Mapping[str, Any],
    optimization: Mapping[str, Any],
) -> bool:
    source_manifest = _plain_mapping(optimization.get("source_manifest"))
    source_metadata = _plain_mapping(source_manifest.get("metadata"))
    source_optimization = _plain_mapping(source_manifest.get("optimization"))
    target = _plain_mapping(_plain_mapping(source_optimization.get("target")))
    metadata = {
        **source_metadata,
        **_plain_mapping(target.get("metadata")),
    }
    if _scope_key(metadata.get("task_kind")) == "redteam_attack_evolution":
        return True

    best_config = _plain_mapping(optimization.get("best_config"))
    simulation = _plain_mapping(best_config.get("simulation"))
    environment_types = {
        _scope_key(_plain_mapping(item).get("type"))
        for item in _plain_list(simulation.get("environments"))
        if _plain_mapping(item)
    }
    if environment_types & {
        "red_team_attack_evolution",
        "redteam_attack_evolution",
        "attack_evolution",
    }:
        return True

    selected_history = _selected_optimization_history(payload, optimization)
    report_state = _selected_report_environment_state(selected_history)
    return "red_team_attack_evolution" in report_state


def _is_orchestration_stack_optimization(
    payload: Mapping[str, Any],
    optimization: Mapping[str, Any],
) -> bool:
    source_manifest = _plain_mapping(optimization.get("source_manifest"))
    source_metadata = _plain_mapping(source_manifest.get("metadata"))
    source_optimization = _plain_mapping(source_manifest.get("optimization"))
    target = _plain_mapping(_plain_mapping(source_optimization.get("target")))
    metadata = {
        **source_metadata,
        **_plain_mapping(target.get("metadata")),
    }
    if _scope_key(metadata.get("task_kind")) == "orchestration_stack":
        return True

    required_environment_types = {
        "world_contract",
        "framework_trace",
        "retrieval_memory",
        "agent_memory_lineage",
        "multi_agent_room",
    }
    best_config = _plain_mapping(optimization.get("best_config"))
    simulation = _plain_mapping(best_config.get("simulation"))
    environment_types = {
        _scope_key(_plain_mapping(item).get("type"))
        for item in _plain_list(simulation.get("environments"))
        if _plain_mapping(item)
    }
    if required_environment_types.issubset(environment_types):
        return True

    selected_history = _selected_optimization_history(payload, optimization)
    state_keys = set(_selected_report_environment_state(selected_history))
    if {
        "world_contract",
        "framework_trace",
        "retrieval_memory",
        "agent_memory_lineage",
        "multi_agent",
    }.issubset(state_keys):
        return True

    strategy = _plain_mapping(payload.get("orchestration_strategy"))
    present_layers = {
        _scope_key(layer) for layer in _plain_list(strategy.get("present_layers"))
    }
    return strategy.get("kind") == "orchestration_strategy_map" and {
        "world",
        "framework",
        "retrieval",
        "memory",
        "multi_agent",
    }.issubset(present_layers)


def _proof_check(
    check_id: str,
    *,
    passed: bool,
    required: bool,
    reason: str,
    evidence: Mapping[str, Any],
) -> dict[str, Any]:
    return {
        "id": check_id,
        "status": "passed" if passed else "failed" if required else "warning",
        "passed": bool(passed),
        "required": bool(required),
        "reason": reason,
        "evidence": copy.deepcopy(dict(evidence)),
    }


def _world_hook_check(
    check_id: str,
    *,
    passed: bool,
    required: bool,
    reason: str,
    evidence: Mapping[str, Any],
) -> dict[str, Any]:
    return _proof_check(
        check_id,
        passed=passed,
        required=required,
        reason=reason,
        evidence=evidence,
    )


def _present_nested_keys(value: Any, keys: set[str]) -> set[str]:
    present: set[str] = set()
    if isinstance(value, Mapping):
        for key, item in value.items():
            key_text = str(key)
            if key_text in keys:
                present.add(key_text)
            present.update(_present_nested_keys(item, keys))
    elif isinstance(value, list):
        for item in value:
            present.update(_present_nested_keys(item, keys))
    return present


def _contains_nested_keys(value: Any, keys: set[str]) -> bool:
    return bool(_present_nested_keys(value, keys))


def _resolved_artifact_action_args(
    action: Mapping[str, Any],
    inputs: Mapping[str, Any],
) -> list[str]:
    defaults = {
        str(item.get("name")): item.get("default")
        for item in action.get("inputs") or []
        if isinstance(item, Mapping)
        and item.get("name") not in (None, "")
        and item.get("default") is not None
    }
    values = {**defaults, **{str(key): value for key, value in inputs.items()}}
    resolved: list[str] = []
    for raw_arg in action.get("command_args") or []:
        arg = str(raw_arg)
        for key, value in values.items():
            arg = arg.replace("{{" + key + "}}", str(value))
        if "{{" in arg or "}}" in arg:
            raise ValueError(f"action {action.get('id')!r} has unresolved input")
        resolved.append(arg)
    return resolved


